[782] = {"破碎的聯盟", {"殺掉索葛蘭，把大地印章交給卡加斯的高恩。"}},
[783] = {"身邊的危機", {"與治安官瑪克布萊德談話。"}},
[784] = {"背信棄義的人類", {"殺死10個庫爾提拉斯水手和8個庫爾提拉斯水兵，再把本尼迪克上尉幹掉，然後回剃刀嶺向加索克復命。"}},
[786] = {"科卡爾半人馬的進攻", {"在森金村外面的拉爾·獵齒要求你粉碎科卡爾峭壁內的三份進攻計畫。"}},
[788] = {"小試身手", {"殺掉10隻雜斑野豬，然後向大獸穴裡的高內克報告。"}},
[789] = {"工蠍的尾巴", {"帶10根工蠍的尾巴給大獸穴中的高內克。"}},
[790] = {"薩科斯", {"殺死薩科斯並將它的爪子帶回去交給哈納祖。"}},
[791] = {"新的背包", {"剃刀嶺瞭望塔中的弗恩·凝眉想要8塊帆布腳料。"}},
[792] = {"邪靈劣魔", {"殺死12隻邪靈劣魔，然後向大獸穴外的祖雷薩覆命。"}},
[793] = {"破碎的聯盟", {"用大地印章啟動鑽石柱、蛋白石柱和紫水晶石柱並拿到三顆符石。","","把符石放在大地封印上，釋放黑龍布萊克拉席和赫瑪圖斯。","","殺了這兩條黑龍，把黑龍布萊克拉席的鎖鏈、赫瑪圖斯的鎖鏈和大地印章交給高恩。"}},
[794] = {"燃刃勳章", {"給大獸穴外的祖雷薩帶回燃刃勳章。"}},
[795] = {"大地封印", nil},
[804] = {"薩科斯", {"將哈納祖目前的狀況告訴大獸穴內的高內克。"}},
[805] = {"去森金村報到", {"與森金村的加德林大師談話。"}},
[806] = {"黑暗風暴", {"把費索的爪子帶給剃刀嶺的奧戈尼爾·魂痕。"}},
[808] = {"明希納的顱骨", {"到回音群島上去，將島上法陣中的明希納的顱骨帶回來，交給森金村的加德林大師。"}},
[809] = {"雅克塞羅斯", {"到貧瘠之地去和雅克塞羅斯談話。"}},
[812] = {"救命如救火", {"找到毒尾蠍的解毒劑，把它交給杜洛塔西北邊境的林納格。"}},
