[815] = {"恐龍蛋大餐", {"收集3個鞭尾龍的蛋，並把它們帶給剃刀嶺的廚師托爾卡。"}},
[816] = {"丟失的孩子", {"把關於克魯恩的消息告訴剃刀嶺西北部農場中的米莎·托克倫。"}},
[817] = {"生活所需的虎皮", {"收集四張杜洛塔虎皮，並把它們交給森金村的維爾林·長牙。"}},
