[821] = {"老陳的空酒桶", {"收集5顆草原獅的獠牙、5個平原陸行鳥的腎臟和1根雷霆蜥蜴的角，把它們交給棘齒城的釀酒師德羅恩。"}},
[822] = {"老陳的空酒桶", {"收集5個閃電腺、1個雷鷹的唾液腺和1個科多獸的肝臟，把它們交給棘齒城裡的釀酒師德羅恩。"}},
[823] = {"向奧戈尼爾報告", {"和剃刀嶺的奧戈尼爾·魂痕談話。"}},
[824] = {"陶土議會的耶努薩克雷", {"將被污染的水球交給梣谷左拉姆加前哨站的耶努薩克雷。"}},
[825] = {"海底沉船", {"剃刀嶺的加索克要你從海岸邊的艦隊殘骸中打撈出3件地精的工具。"}},
[826] = {"札拉贊恩", {"打敗札拉贊恩。","","殺死8個巫毒食人妖和8個妖術食人妖。","","把札拉贊恩的頭顱帶給加德林大師。"}},
[827] = {"骷髏石", {"在骷髏石中的火刃祭司身上收集灼熱項圈，","","然後交給瑪高茲。"}},
