[829] = {"尼爾魯·火刃", {"給奧格瑪的尼爾魯·火刃帶去一個項圈樣本。"}},
[830] = {"將軍的命令", {"把普勞德摩爾將軍的命令帶給剃刀嶺的加索克。"}},
[831] = {"將軍的命令", {"把普勞德摩爾將軍的命令交給奧格瑪城中的納茲格雷爾，他就在索爾的大廳裡。"}},
