[836] = {"拯救OOX-09/HL！", {"將OOX-09/HL護送到被遺忘的海岸上的碼頭，然後向藏寶海灣的奧格索普·奧布諾提斯報告。"}},
[837] = {"野豬人的進犯", {"替剃刀嶺的加索克殺掉4個鋼鬃野豬人，4個鋼鬃斥候，4個鋼鬃傳令兵和4個鋼鬃衛兵。"}},
