[840] = {"部落的新兵", {"沿著剃刀嶺西部的小路一直前進，過橋之後就可以進入貧瘠之地。","","在橋對面的獸人前哨找到卡加爾·戰痕，將你的募兵信交給他。"}},
[841] = {"另一個能量源？", {"用10個廢土水袋來和加基森的總工程師比格維茲換取另外一個能量源。"}},
[842] = {"十字路口的徵兵行動", {"從卡加爾的前哨站往西走。","","在T字路口左轉，然後朝南走。","","在十字路口的道路交匯處找尋瑟格拉·黑棘。"}},
[843] = {"加恩的報復", {"加恩·石塔讓你殺死15個巴爾丹挖掘者和5個巴爾丹工頭。","","把卡茲戈姆的日記交給加恩·石塔。"}},
[844] = {"平原陸行鳥的威脅", {"收集7個陸行鳥的喙，把它們交給十字路口的瑟格拉·黑棘。"}},
[845] = {"斑馬的威脅", {"殺死快步斑馬並收集4隻斑馬蹄，把它們交給十字路口的瑟格拉·黑棘。"}},
