[2338] = {"翻譯日記", {"將項鏈借給加卡爾。作為交換，他將幫你翻譯日記。"}},
[2339] = {"尋找寶貝", {"從奧達曼找回項鏈上的所有三塊寶石和能量源，然後把它們交給卡加斯的加卡爾。","","紅寶石被藏在暗影矮人層層設防的地區。","","黃寶石藏在穴居怪活動地區的一個甕中。","","藍寶石在格瑞姆洛克手中，他是穴居怪的領袖。","","能量源可能在奧達曼的某個最強生物的手中。"}},
[2340] = {"運送寶石", {"把項鏈和寶石送到奧格瑪的德蘭·杜佛斯那裡。"}},
[2341] = {"項鏈任務的終結", {"去卡加斯看看加卡爾是否成功了。"}},
[2342] = {"尋找寶物", {"從奧達曼南部大廳的箱子中找到加勒特的家族寶藏，然後把它交給幽暗城的派翠克·加瑞特。"}},
[2359] = {"克拉文之塔", {"偷取迪菲亞塔樓鑰匙，進入迪菲亞塔樓，看看暮色森林的箱子裡到底有什麼東西，然後向暴風城的馬迪亞斯·肖爾彙報。"}},
