[2361] = {"修復項鏈", nil},
[2378] = {"尋找碎手氏族", {"前往奧格瑪，和暗影裂口那的申蘇爾談話。"}},
[2379] = {"贊杜沙", {"與暗影裂口的贊杜沙談話。"}},
[2381] = {"搶劫海盜", {"把南海寶藏帶回給棘齒城的卑鄙的維尼克斯。不要忘了從維尼克斯的機械設備中拿取一份大餅乾和盜賊工具，你的任務需要使用這兩件東西。","","如果你被任何奇怪的鸚鵡攻擊，就對它使用大餅乾！"}},
[2382] = {"棘齒城的維尼克斯", {"到棘齒城去，與卑鄙的維尼克斯談話。"}},
