[2438] = {"翡翠攝夢符", {"將翡翠攝夢符交給多蘭納爾的塔隆凱·捷根。"}},
[2439] = {"白金圓盤", {"把你的報酬憑證交給鐵爐堡銀行的丁尼塔·石衣。"}},
[2440] = {"白金圓盤", {"把報酬憑證交給雷霆崖的貝娜·冰蹄。"}},
[2458] = {"臥底密探", {"到淤泥沼澤北邊的風險投資公司塔樓去，聯繫碎手氏族的臥底費蘇勒。","","看到塔樓之後，用信號槍發射信號，向工頭費蘇勒示意你已經到達。發出兩個閃光信號，然後使用碎手軍禮和工頭費蘇勒接頭。","","注意，這些步驟必須依次進行，因為費蘇勒會攻擊並幹掉任何他無法識別的人。"}},
[2459] = {"噬夢者菲羅斯塔", {"多蘭納爾的塔隆凱·捷根要你殺掉7個瘤背秘法師，並找到遺失的珠寶。"}},
[2460] = {"碎手軍禮", {"對著申蘇爾練習碎手軍禮。"}},
[2478] = {"基本不可能的任務", {"從工頭希里克斯那裡偷出希里克斯的塔樓鑰匙，進入塔樓，然後殺掉兩個變異風險投資公司工人、兩個風險投資公司巡邏員、兩個風險投資公司看守。","","殺掉大工頭普茲克·加里維克斯，取了他的首級，然後打開加里維克斯的箱子，拿走贊吉爾的改良藥劑。將藥劑和加里維克斯的頭顱交給奧格瑪的申蘇爾，等候進一步的指示。"}},
[2479] = {"希諾特的幫助", {"到希爾斯布萊德丘陵的塔倫米爾去，把贊吉爾的藥劑樣品交給瑟爾格·希諾特。","","要去塔倫米爾，可以搭乘飛艇到幽暗城，然後沿著大路向南穿過銀松森林，直到希爾斯布萊德丘陵。跟著路標走！"}},
[2480] = {"希諾特的幫助", {"等待瑟爾格·希諾特完成解藥。"}},
[2498] = {"向德納蘭回報", {"雷利亞·綠樹要你和奧拉密斯湖的德納蘭談一談。"}},
[2499] = {"奧肯斯古爾", {"奧拉密斯湖的德納蘭要你去拿到奧肯斯古爾身上的巨大的瘤。"}},
[2500] = {"荒蕪之地的材料", {"從荒蕪之地拿到加克所需的材料，然後回到塞爾薩瑪去見他。"}},
[2518] = {"月神的淚水", {"達納蘇斯月神殿的女祭司艾茉拉讓你把薩絲拉的銀色絲囊交給她。"}},
