[2561] = {"利爪德魯伊", {"奧本·怒爪要求你去殺掉他那失去靈魂的身體，然後對其屍體使用巫毒符咒。"}},
[2581] = {"彎牙土狼的顎骨", {"收集3個彎牙土狼的顎骨、2片詛咒之地的野豬肺和1個厚甲蠍螯，把它們交給血法師德拉吉亞。"}},
