[2962] = {"更多的輻射塵！", {"到諾姆瑞根去收集高強度輻射塵。要多加小心，這種輻射塵非常不穩定，很快就會分解。","","奧齊要求你在任務完成後把沉重的鉛瓶也交給他。"}},
