[3509] = {"惡魔之名", {"與艾薩拉的亞考羅克談一談。你應該在海邊搜索亞考蘭神殿。"}},
[3510] = {"惡魔之名", {"殺掉赫塔拉，將染血的赫塔拉頭顱、破碎的赫塔拉頭顱和淤血的赫塔拉頭顱交給亞考羅克。"}},
[3511] = {"惡魔之名", {"將調劑交給洛拉姆斯·薩里比迪斯。"}},
[3512] = {"幫助伊蘭尼庫斯", {"到冬泉谷的東部地區去，與靈語者阿姆布蘭希談話。"}},
[3513] = {"符文卷軸", {"將符文卷軸帶到貧瘠之地的北部警戒塔去。"}},
[3514] = {"部落的示威", {"殺死猛禽洞穴的領袖琳薩瑞爾。"}},
[3517] = {"偷竊知識", {"為瓦羅莫克的傑迪加找到貝薩瑪拉石板、辛耶爾石板、瑪寇里石板和塞爾哈石板。"}},
[3518] = {"送貨給瑪加薩‧恐怖圖騰", {"將貝薩瑪拉石板交給雷霆崖的瑪加薩‧恐怖圖騰。"}},
[3519] = {"需要幫助的朋友", {"與幽影谷的迪蘭妮亞·銀光談話。"}},
[3520] = {"尖嘯者的靈魂", {"到菲拉斯捕獲3個尖叫者的靈魂，然後回到熱砂港的葉金亞那裡。"}},
[3521] = {"埃沃隆的解藥", {"在幽影谷中為迪蘭妮亞·月光收集7朵紫藍色蘑菇、4朵月牙百合花和一份樹林蜘蛛的膿液。"}},
[3522] = {"埃沃隆的解藥", {"在5分鐘內將埃沃隆的解藥交給他。你可以從在北邊的洞穴旁找到埃沃隆。"}},
[3523] = {"剃刀高地的天譴軍團", {"要是你願意幫助貝尼斯特拉茲，再跟他談談，並將黑曜石還給他。"}},
[3524] = {"擱淺的巨獸", {"在奧伯丁南邊的海岸上尋找擱淺生物的駭骨，然後帶著骨頭回來找奧伯丁的溫尼斯·布萊葛。"}},
[3525] = {"封印神像", {"護送貝尼斯特拉茲來到剃刀高地的野豬人神像處。","","當他在執行儀式封印石像時保護他。"}},
[3527] = {"摩沙魯的預言", {"將第一塊和第二塊摩沙魯石板交給塔納利斯的葉基亞。"}},
[3528] = {"神靈哈卡", {"將裝滿的哈卡之卵交給塔納利斯的葉基亞。"}},
[3541] = {"送貨給傑斯雷蒙", {"將辛耶爾石板交給奧格瑪的傑斯雷蒙。"}},
[3542] = {"送貨給安德隆·甘特", {"將瑪寇里石板交給幽暗城的安德隆·甘特。"}},
[3561] = {"送貨給大法師克希雷姆", {"將塞爾哈石板交給艾薩拉的大法師克希雷姆。"}},
[3562] = {"瑪加薩的報酬", {"將瑪加薩的便箋交給艾薩拉的傑迪加。"}},
[3563] = {"傑斯雷蒙的報酬", {"將傑斯雷蒙的便箋交給艾薩拉的傑迪加。"}},
[3564] = {"安德隆的報酬", {"將安德隆的字條交給艾薩拉的傑迪加。"}},
[3565] = {"克希雷姆的報酬", {"將克希雷姆的便箋交給艾薩拉的傑迪加。"}},
[3566] = {"奧比斯頓", {"殺死黑衣拉索里克和奧比斯頓，帶著黑衣拉索里克的頭顱和奧比斯頓的心臟回到鐵爐堡的索里奧斯那裡。"}},
[3567] = {"登高", nil},
[3568] = {"墮落之水", {"在艾薩拉的埃達拉斯廢墟旁的海潮之池中收集4瓶水，然後回到藥劑師科雷那兒。"}},
[3569] = {"墮落之水", {"將科雷的藥劑交給幽暗城的瑟爾薩·風歌。"}},
[3570] = {"墮落之水", nil},
[3601] = {"我就是基姆加爾！", {"搜索薩拉斯營地，尋找基姆加爾的指南針，望遠鏡，燒雞和花生，然後將它們交還給艾薩拉的基姆加爾。"}},
[3602] = {"艾薩拉水晶", {"在艾薩拉南部收集20塊艾薩拉晶體。你可以使用地獄犬協助尋找一些隱藏的礦脈。","","任務完成之後就回到洛拉姆斯那裡去。"}},
[3621] = {"武器的鑄造", {"把貨物交給荊棘谷的加爾文。"}},
[3625] = {"魔化艾薩拉水晶武器", {"等待加爾文為你鍛造武器。"}},
[3626] = {"返回詛咒之地", {"回到部落英雄的靈魂那裡。"}},
[3627] = {"收集破碎的護符", {"殺掉毀滅者戈洛爾、瑟溫妮，以及大法師奧利斯塔。從他們到屍體上拿到戈洛爾的護符、瑟溫妮的護符和奧利斯塔的護符。","","記住使用你的魔化艾薩拉水晶武器<name>削弱他們，否則他們是無法被殺死的——你必須小心謹慎地使用你的武器……"}},
[3629] = {"哥布林工程學", {"如果你想要對哥布林工程學有更多瞭解，就把工程學教材交給加基森的尼克斯·斯普克斯賓。"}},
[3631] = {"召喚地獄戰馬", {"與貧瘠之地棘齒城的斯坦哈德·法爾杉談話。"}},
[3636] = {"與聖光同在", {"大主教本尼迪塔斯要你去殺死剃刀高地的『寒冰使者』亞門納爾。"}},
[3637] = {"地精工程學", {"如果你想要對地精工程學有更多瞭解，就把工程學教材交給藏寶海灣的奧格索普·奧布諾提斯。"}},
[3639] = {"工作成果", {"將20顆重磅鐵製炸彈、20顆實心炸彈和5隻自爆綿羊交給加基森的尼克斯·斯普克斯賓。"}},
[3645] = {"會員卡續費", nil},
[3661] = {"月神之獸？", {"為魯瑟蘭村的艾瑞拉斯·琥珀收集15支梟獸羽毛。"}},
[3701] = {"索瑞森廢墟", {"到燃燒平原的索瑞森廢墟中去，從索瑞森聖物上搜集資訊。當你收集到足夠的資訊之後，就回到皇家歷史學家阿克瑟努斯那裡。"}},
[3702] = {"索瑞森廢墟", {"聽皇家歷史學家阿克瑟努斯講述索瑞森的歷史。"}},
[3721] = {"你自己的OOX", nil},
[3741] = {"希拉蕊的項鏈", {"找到希拉蕊的項鏈，將其還給湖畔鎮的希拉蕊。"}},
[3761] = {"安戈洛的泥土", {"收集20份安戈洛的泥土，把它們交給雷霆崖的格德。"}},
[3762] = {"協助大德魯伊", {"與雷霆崖的大德魯伊哈繆爾·符文圖騰談話。"}},
[3763] = {"協助大德魯伊", {"與達納蘇斯的大德魯伊范達爾·鹿盔談話。"}},
[3764] = {"安戈洛的泥土", {"收集20份安戈洛的泥土，把它們交給達納蘇斯的耶納爾。"}},
[3765] = {"遙遠的旅途", {"到奧伯丁的戈沙拉·夜語那兒去。"}},
[3781] = {"晨光麥研究", {"將大德魯伊的草種購買券交給達納蘇斯城塞納里奧區的瑪斯雷·馭熊者。"}},
[3782] = {"晨光麥研究", {"將草種購買券交給雷霆崖的巴珊娜·符文圖騰。"}},
[3783] = {"雪怪計畫！", {"為永望鎮的烏米收集10張厚雪人毛皮。"}},
[3784] = {"協助大德魯伊", {"與雷霆崖的大德魯伊哈繆爾·符文圖騰談話。"}},
[3785] = {"晨光麥研究", {"用一個常青袋、一包薩倫迪斯種子以及兩份安戈洛的泥土來嘗試種植晨光麥。","","將10株晨光麥交給達納蘇斯的瑪斯雷·馭熊者。"}},
[3786] = {"晨光麥研究", {"用一個常青袋、一包薩倫迪斯種子以及兩份安戈洛的泥土來嘗試種植晨光麥。","","將10株晨光麥交給雷霆崖的巴珊娜·符文圖騰。"}},
[3787] = {"奎恩提斯的請求", {"與羽月要塞的奎恩提斯談話。"}},
[3788] = {"奎恩提斯的請求", {"與羽月要塞的奎恩提斯談話。"}},
[3789] = {"協助大德魯伊", {"與達納蘇斯的大德魯伊范達爾·鹿盔談話。"}},
[3790] = {"協助大德魯伊", {"與達納蘇斯的大德魯伊范達爾·鹿盔談話。"}},
[3791] = {"晨光麥的秘密", {"將10株晨光麥交給羽月要塞的奎恩提斯。"}},
[3801] = {"黑鐵的遺產", {"如果你想要得到進入這座城市主城區的鑰匙，就去和弗蘭克羅恩·鑄鐵談話。"}},
[3802] = {"黑鐵的遺產", {"殺掉弗諾斯·達克維爾並拿回戰錘鐵膽。把鐵膽之錘拿到索瑞森神殿去，將其放在弗蘭克羅恩·鑄鐵的雕像上。"}},
[3803] = {"達納蘇斯的晨光麥", nil},
[3804] = {"雷霆崖的晨光麥", nil},
[3821] = {"巨槌石", {"到燃燒平原去找到沙妮·長齒。"}},
[3822] = {"克羅格盧爾", {"從克羅格盧爾手中拿回沙妮的鼻環，把它還給卡加斯的薩特拉克。搜尋巨槌石的每一處山洞和礦坑。"}},
[3823] = {"消滅火腹巨魔", {"殺掉15個火腹巨魔法師、7個火腹巨魔和7個火腹蠻兵，完成任務之後向奧拉留斯報告。"}},
[3824] = {"蠻王戈泰什", {"找到戈泰什，他應該在巨槌石西面的某處。殺掉戈泰什並把他的頭顱交給燃燒平原的奧拉留斯。"}},
[3825] = {"梟首示眾", {"把戈泰什的頭顱放在巨槌石的山頂上。找一塊軟土堆把串著頭顱的長矛插上去就可以了。"}},
[3841] = {"領養孤兒", {"與千針石林的奎恩丁談話。"}},
[3842] = {"即將孵化", {"將2份次級堅韌藥劑交給千針石林的奎恩丁。"}},
[3843] = {"新的生命", {"帶著這枚脆弱的小精龍卵去辛特蘭，與阿格納談一談，但是你一定要在它還有生命力的時候趕到，在蛋裡的小生命夭折之前，你只有1小時的時間。"}},
[3844] = {"無人知曉的秘密", {"在池塘附近查找與擱淺的小艇有關的線索。"}},
[3845] = {"無人知曉的秘密", {"查看袋子裡的東西，然後將它們交給物主。"}},
[3861] = {"咕咕嘎！", {"找一些特殊的雞飼料，把它交給友好的小雞。當你找到小雞的時候，在餵食它之前對它做出高興的表情。（使用/cheer命令）"}},
[3881] = {"搶救物資", {"將食物箱和研究設備交給安戈洛環形山的威利德·馬紹爾。"}},
[3882] = {"挖骨頭", {"將8根恐龍骨頭交給安戈洛環形山的斯巴克·尼米爾。"}},
[3883] = {"異型的生態", {"使用採集瓶從安戈洛環形山的某個格里什蟲巢的孵化室中收集一份巢穴側壁的樣本，在有懸掛著的蟲卵的房間裡收集樣本。","","將蟲穴內壁樣本交給安戈洛環形山的霍萊伊·馬紹爾。"}},
[3884] = {"威利德的日記", {"將日記還給安戈洛環形山中的威利德·馬紹爾。"}},
[3901] = {"斷骨骷髏", {"殺掉12個斷骨骷髏，然後回到喪鐘鎮的暗影牧師薩維斯那裡。"}},
[3902] = {"撿破爛", {"在喪鐘鎮及臨近地區搜尋6件破爛裝備，把它們交給亡靈衛兵薩爾坦。"}},
[3903] = {"米莉·奧斯沃斯", {"與米莉·奧斯沃斯談話。"}},
[3904] = {"米莉的葡萄", {"收集8箱米莉的葡萄，把它們交給北郡修道院的米莉·奧斯沃斯。"}},
[3905] = {"葡萄出貨單", {"將葡萄出貨單交給北郡修道院的尼爾斯修士。"}},
[3906] = {"不和諧的烈焰", {"到黑石山脈的採石場去幹掉征服者派隆，然後向桑德哈特回報。"}},
[3907] = {"不和諧的火焰", {"進入黑石深淵並找到伊森迪奧斯。殺掉它，然後把你找到的資訊彙報給桑德哈特。"}},
[3908] = {"無人知曉的秘密", {"把林克的劍交給冬泉谷的多諾瓦·雪山。"}},
[3909] = {"視靈藥劑", {"去菲拉斯找格雷甘·山酒。從他那裡問到獲取視靈藥劑的方法，然後向冬泉谷的多諾瓦·雪山覆命。"}},
[3912] = {"墓地相見", {"在加基森鎮外的墓地中使用視靈藥劑，然後按照多諾瓦的指示找到加里楊。"}},
[3913] = {"尋找墓碑", {"復活，然後尋找加里楊讓你去找的那塊墓碑。"}},
[3914] = {"林克的劍", {"把林克的強化之劍交給安戈洛環形山的林克。"}},
[3921] = {"維妮·布特巴克", {"將損壞的主動式負載平衡器交給維妮·布特巴克。"}},
[3922] = {"高強度齒輪", {"把15個高強度齒輪交給貧瘠之地的維妮·布特巴克。"}},
[3923] = {"雷里·格里斯高布", {"把破碎的主動式負載平衡器交給奧格瑪的雷里·格里斯高布。"}},
[3924] = {"主動式負載平衡器說明書", {"把主動式負載平衡器說明書交給奧格瑪的雷里·格里斯高布。"}},
[3941] = {"地精的援助", {"到馬紹爾營地那裡的山洞中去找科琳。"}},
[3942] = {"林克的記憶", {"到費伍德森林去找艾瑞丹·藍風。"}},
[3961] = {"林克的冒險", {"把亞奎門塔斯的銀圖騰交給馬紹爾營地裡的林克。"}},
[3962] = {"結伴而行", {"到馬紹爾營地南邊的火羽山去。","","找到火焰使者，並使用圖騰除掉它的防護光環。在擊敗它之後從洞中取得金色火焰。"}},
[3981] = {"指揮官哥沙克", {"在黑石深淵裡找到指揮官哥沙克。","","在那幅草圖上畫著的是一個鐵欄後面的獸人，也許你應該到某個類似監獄的地方去找找看。"}},
[3982] = {"出了什麼事？", {"保護哥沙克。"}},
[4001] = {"出了什麼事？", {"與卡蘭·巨錘談一談，收集關於綁架公主鐵爐堡公主茉艾拉·銅鬚這一事件的情報。將情報回饋給奧格瑪城裡的索爾。","","哥沙克提到過卡蘭被關在附近的某個牢房中。"}},
[4002] = {"東部王國", {"如果你準備好要接受索爾所安排的任務，就去找他談話。"}},
[4003] = {"拯救公主", {"殺掉達格蘭·索瑞森大帝，然後將鐵爐堡公主茉艾拉·銅鬚從他的邪惡詛咒中拯救出來。"}},
[4004] = {"拯救公主？", {"向索爾報告！"}},
[4005] = {"亞奎門塔斯", {"把阿奎爾之書、銀爪，還有鐵樹心帶到塔納利斯。","","用這本書召喚亞奎門塔斯。","","當你完成圖騰之後，把它帶給在馬紹爾營地的科琳。"}},
[4021] = {"人馬無雙！", {"將克羅姆札軍旗的碎片交給十字路口西邊的雷戈薩·死門。"}},
[4022] = {"烈焰精華", {"向塞勒斯·薩雷芬圖斯展示你從維拉若克·溫布雷那裡得到的黑龍軍團之皮。"}},
[4023] = {"烈焰精華", {"向塞勒斯·薩雷芬圖斯證明你的價值。","","你感覺到塞勒斯似乎對你不屑一顧。"}},
[4024] = {"烈焰精華", {"到黑石深淵去殺掉貝爾加。","","你只知道這個巨型怪物住在黑石深淵的最深處。記住你要使用特殊的黑龍皮從貝爾加的屍體上採集烈焰精華。","","將你採集到的烈焰精華交給塞勒斯·薩雷芬圖斯。"}},
[4041] = {"視靈藥劑", nil},
[4061] = {"機器的崛起", {"到燃燒平原去為塞朵拉·穆瓦丹尼收集10塊斷裂的元素碎片。","","塞朵拉曾經說過，那裡的機械傀儡和元素生物是這種碎片的主要來源。"}},
[4062] = {"機器的崛起", {"將元素碎片樣本交給魯特維爾·沃拉圖斯。","","塞朵拉說魯特維爾就在東邊的一處營地裡。"}},
[4063] = {"機器的崛起", {"找到並殺掉傀儡統帥阿格曼奇，將他的頭交給魯特維爾。你還需要從守衛著阿格曼奇的狂怒傀儡和戰鬥傀儡身上收集10塊完整的元素核心。"}},
[4081] = {"格殺勿論：黑鐵矮人", {"到黑石深淵去消滅那些邪惡的侵略者！","","指揮官高圖斯要你去殺死15個鐵怒衛士、10個鐵怒獄卒和5個鐵怒步兵。完成任務之後回去找他。"}},
[4082] = {"格殺勿論：高階黑鐵軍官", {"到黑石深淵去消滅那些邪惡的侵略者！","","高圖斯軍閥要你殺死10個鐵怒醫師,、10個鐵怒士兵和10個鐵怒軍官。完成任務之後回去向他覆命。"}},
[4083] = {"鬼魂之杯", nil},
[4084] = {"銀爪鐵心", {"為費伍德森林的艾瑞丹·藍風收集11隻銀爪和1顆鐵樹之心。"}},
[4101] = {"淨化費伍德", {"收集15顆血琥珀，把它們交給費伍德森林的阿拉珊蒂絲·銀空。"}},
[4102] = {"淨化費伍德", {"收集15顆血琥珀，把它們交給費伍德森林的梅貝絲·河風。"}},
