[4116] = {"被腐化的輕歌花", nil},
[4119] = {"被腐化的夜龍草", nil},
[4120] = {"腐化的力量", {"菲拉斯莫沙徹營地的塔羅·刺蹄要你去費伍德森林殺掉12頭怒爪灰熊和12頭魔爪掠奪者。"}},
[4121] = {"押送囚徒", {"押送你的囚犯格拉克·洛克魯布。穿過燃燒平原和黑石山脈，一直走到灼熱峽谷。","","雷克斯洛特曾經告訴過你，他會讓他的人等在黑石山脈的另外一邊準備接收格拉克。","","另外，你還要把瑟銀鐐銬一併還給雷克斯洛特。"}},
[4122] = {"格拉克·洛克魯布", {"到燃燒平原去找到格拉克·洛克魯布。你回憶起雷克斯洛特曾經提起過，格拉克應該是在一座大型的黑石要塞中。","","當你找到格拉克·洛克魯布之後，用瑟銀鐐銬把他銬起來，然後將其帶回灼熱峽谷。雷克斯洛特會讓他的部下等在那裡接應你。"}},
[4123] = {"山脈之心", {"把山脈之心交給燃燒平原的麥克斯沃特·尤柏格林。"}},
[4124] = {"失蹤的信差", {"和羽月要塞的基恩諾·火花談話。"}},
[4125] = {"失蹤的信差", {"找到信差的小船，你應該在菲拉斯的南部海岸線上展開搜索。"}},
[4126] = {"霍爾雷·黑鬚", {"把遺失的雷酒秘方帶給卡拉諾斯的拉格納·雷酒。"}},
[4127] = {"船隻的殘骸", {"回到羽月要塞，給基恩諾·火花看看你找到的這把被丟棄的小刀。"}},
[4128] = {"拉格納·雷酒", {"和拉格納·雷酒談談。"}},
[4129] = {"奎恩提斯的技藝", {"把被丟棄的小刀交給羽月要塞的奎恩提斯。"}},
[4130] = {"心靈占卜術", {"和羽月要塞的基恩諾·火花談話。"}},
[4131] = {"木爪豺狼人", {"在菲拉斯南部地區的木爪豺狼人營地裡尋找信差的下落或者信差的物品。"}},
[4132] = {"行動：殺死安格弗將軍", {"到黑石深淵去殺掉安格弗將軍！當任務完成之後向軍官高圖斯覆命。"}},
[4133] = {"薇薇安·拉格雷", {"與卡加斯的暗法師薇薇安·拉格雷談話。"}},
[4134] = {"遺失的雷酒秘方", {"把遺失的雷酒秘方交給卡加斯的薇薇安·拉格雷。"}},
[4136] = {"雷布里·斯庫比格特", {"把雷布里的頭顱交給燃燒平原的尤卡·斯庫比格特。"}},
[4141] = {"莫爾金和拉里安", {"從安戈洛環形山的血瓣花猛擊者和血瓣花掠奪者身上收集20個血瓣花，然後向莫爾金回復。"}},
[4142] = {"造訪格雷甘", {"把血瓣花交給菲拉斯的格雷甘·山酒。"}},
[4143] = {"邪惡之霧", {"收集5份阿塔萊之霧的樣本，然後向安戈洛環形山的莫爾金覆命。"}},
[4144] = {"血瓣花苗", nil},
[4145] = {"拉里安和莫爾金", {"為馬紹爾營地裡的拉里安殺掉10個血瓣花鞭笞者和10個血瓣花捕獸者。"}},
[4146] = {"除草器的燃料", {"收集5份阿塔萊之霧的樣本，然後將它們送到馬紹爾營地的拉里安那裡。"}},
[4147] = {"瑪爾馮的工坊", {"到棘齒城去，在瑪爾馮·瑞文斯克的工坊裡找到他。"}},
[4148] = {"血瓣花除草器", nil},
[4161] = {"卡多雷的菜譜", {"為多蘭納爾的札瑞恩收集7條小蜘蛛腿。"}},
[4182] = {"黑龍的威脅", {"殺掉15條黑色小龍、10條黑色龍人和1條黑色幼龍。當你完成任務之後就向赫林迪斯·河角回報。"}},
[4183] = {"真正的主人", {"把赫林迪斯·河角的信交給湖畔鎮的所羅門鎮長。"}},
[4184] = {"真正的主人", {"到暴風城去把所羅門的求援信交給伯瓦爾·弗塔根公爵。","","伯瓦爾在暴風要塞裡。"}},
[4185] = {"真正的主人", {"與女伯爵卡特拉娜·普瑞斯托談話，然後再與伯瓦爾·弗塔根公爵談話。"}},
[4186] = {"真正的主人", {"把伯瓦爾的命令交給湖畔鎮的所羅門鎮長。"}},
[4201] = {"愛情藥水", {"將4份格羅姆之血、10塊巨型銀礦和裝滿水的娜瑪拉之瓶交給黑石深淵的娜瑪拉小姐。"}},
[4222] = {"被腐化的迎風花", nil},
[4223] = {"真正的主人", {"和燃燒平原的麥克斯韋爾元帥談話。"}},
[4224] = {"真正的主人", {"和狼狽不堪的約翰談談來瞭解溫德索爾元帥的命運，然後回到麥克斯韋爾元帥那裡。","","你想起麥克斯韋爾元帥說過他在一個北面的洞穴那裡。"}},
[4241] = {"溫德索爾元帥", {"到西北部的黑石山脈去，在黑石深淵中找到溫德索爾元帥的下落。","","狼狽不堪的約翰曾告訴你說溫德索爾被關進了一個監獄。"}},
[4242] = {"被遺棄的希望", {"把這個壞消息傳達給麥克斯韋爾元帥。"}},
[4243] = {"找回A-Me 01", {"在安戈洛環形山找到A-Me 01。"}},
[4244] = {"找回A-Me 01", {"找到一個秘銀外殼，然後回到安戈洛環形山的A-Me 01身邊。"}},
[4245] = {"找回A-Me 01", {"將A-Me 01交給安戈洛環形山的卡爾納·雷塔維。"}},
[4262] = {"征服者派隆", {"殺掉征服者派隆，然後向加琳達覆命。","","加琳達告訴過你，派隆守在採礦場中，也許你應該去那裡找找。"}},
[4263] = {"伊森迪奧斯！", {"在黑石深淵裡找到伊森迪奧斯，然後把他幹掉！"}},
[4265] = {"逃離蟲巢", {"將拉斯卡爾安全護送到祖卡什蟲巢外。","","回到羽月要塞的基恩諾·火花那兒，告訴他拉斯卡爾還活著，且狀況良好。"}},
[4266] = {"羽月將軍的歡迎", {"與羽月要塞的珊蒂斯·羽月談話。"}},
[4267] = {"異種蠍的崛起", {"把拉斯卡爾的報告交給達納蘇斯的格拉希娜·靈風。"}},
[4281] = {"薩蘭納爾的貨物", {"將未遞送的包裹交給薩蘭納爾驛站的法芬德爾。"}},
[4282] = {"一絲希望", {"找回溫德索爾元帥遺失的情報。","","溫德索爾元帥確信那些情報在安格弗將軍和傀儡元帥阿格曼奇的手裡。"}},
[4283] = {"五十個！", {"奧拉留斯想要50枚黑石徽章。在燃燒平原的獸人身上應該可以找到那些徽章。"}},
[4284] = {"能量水晶", {"收集紅色能量水晶、藍色能量水晶、黃色能量水晶和綠色能量水晶各7塊，把它們交給馬紹爾營地裡的科琳。"}},
[4285] = {"北部水晶塔", {"在安戈洛環形山找到北部水晶塔。"}},
[4286] = {"好東西", {"到黑石深淵去找到20個黑鐵挎包。當你完成任務之後，回到奧拉留斯那裡覆命。你認為黑石深淵裡的黑鐵矮人應該會有這些黑鐵挎包。"}},
[4287] = {"東部水晶塔", {"在安戈洛環形山找到東部水晶塔。"}},
[4288] = {"西部水晶塔", {"在安戈洛環形山找到西部水晶塔。"}},
[4289] = {"安戈洛的猩猩", {"將2塊安戈洛猩猩的皮、2塊安戈洛大猩猩的皮和2塊安戈洛巨猩猩的皮交給安戈洛環形山入口處的托爾瓦·尋路者。"}},
[4290] = {"拉克維的食物", {"找到拉克維剛剛獵殺的動物的屍體，從屍體上偷取一塊蛇頸龍肉塊，然後回到安戈洛環形山的托爾瓦·尋路者那裡。"}},
[4291] = {"拉克維的氣味", {"將2份暴掠龍資訊素交給安戈洛環形山入口附近的托爾瓦·尋路者。"}},
[4292] = {"拉克維的誘餌", {"使用托爾瓦的麻袋中的東西召喚拉克維並打敗它。將拉克維的頭顱交給安戈洛環形山入口處的托爾瓦·尋路者。"}},
[4293] = {"軟泥怪的樣本…", {"從費伍德的軟泥怪身上收集費伍德軟泥怪樣本，然後使用幽暗城的化學家弗雷身旁的測試設備來檢測你所收集的樣本中哪一份被腐化的程度最深。給化學家弗雷帶去5個被腐化的費伍德樣本。"}},
[4294] = {"一大堆軟泥怪", {"從安戈洛環形山那裡任何泥漿怪身上收集安戈洛泥漿怪樣本。使用幽暗城的化學家弗雷身旁的測試儀器來檢驗你所採集到的樣本的純度。把5份純淨的安戈洛樣本送到化學家弗雷那裡去。"}},
[4295] = {"羅克諾特的麥酒", nil},
[4296] = {"七賢石板", {"把石板拓文交給燃燒平原的麥克斯沃特·尤柏格林。"}},
[4297] = {"小精龍的食物", {"將5塊銀鬃捕獵者的肉交給辛特蘭的阿格納。"}},
[4298] = {"為人父母", {"與辛特蘭的阿格納談話。"}},
[4300] = {"骨刃武器", {"將8隻白色暴掠龍爪交給奧格瑪的傑斯雷蒙。"}},
[4301] = {"強大的尤爾查", {"把尤爾查的毛皮交給安戈洛環形山入口處的托爾瓦·尋路者。"}},
[4321] = {"分析水晶塔", {"過一會再和科琳說話。"}},
[4324] = {"尤卡·斯庫比格特", {"與燃燒平原的尤卡·斯庫比格特談話。"}},
[4341] = {"卡蘭·巨錘", {"去黑石深淵找到卡蘭·巨錘。","","國王提到卡蘭在那裡負責看守囚犯——也許你應該在監獄附近尋找他。"}},
[4342] = {"卡蘭的故事", {"聽卡蘭·巨錘說他的故事。"}},
