[4361] = {"糟糕的消息", {"回到鐵爐堡，把這個壞消息帶給國王麥格尼·銅鬚。"}},
[4362] = {"王國的命運", {"回到黑石深淵，從達格蘭·索瑞森大帝的魔掌中救出鐵爐堡公主茉艾拉·銅鬚。"}},
[4363] = {"語出驚人的公主", {"回到鐵爐堡去，與國王麥格尼·銅鬚談話。"}},
[4401] = {"被腐化的輕歌花", nil},
[4402] = {"戈加爾的清涼果", {"收集10個仙人掌果，把它們交給戈加爾。你記得他說可以在仙人掌上收集到這種果子。"}},
[4421] = {"碧火薩特", {"殺掉11個碧火魔僕、9個碧火巡影者、9個碧火盜賊和薩瓦瑟拉斯。任務完成之後回到費伍德森林的艾瑞丹·藍風處覆命。"}},
[4441] = {"被禁錮的古樹", {"到達納蘇斯去，用艾瑞丹的瓶子收集月神殿中的祝福之水，然後回到艾瑞丹那兒。"}},
[4442] = {"淨化！", {"過一會兒再與艾瑞丹對話。"}},
[4444] = {"被腐化的鞭根草", nil},
[4447] = {"被腐化的夜龍草", nil},
