[4450] = {"塔納利斯的帳本", {"把古德斯迪爾的帳本和上面所列的物品交給塔納利斯的克林科·古德斯迪爾。"}},
[4451] = {"自由的鑰匙", {"搜尋灼熱峽谷並找到一個可以使用這把格里塞特庫房鑰匙的地方。"}},
