[4488] = {"召喚地獄戰馬", {"與棘齒城的斯坦哈德·法爾杉談話。"}},
[4489] = {"召喚地獄戰馬", {"與棘齒城的斯坦哈德·法爾杉談話。"}},
[4490] = {"召喚地獄戰馬", {"與棘齒城的斯坦哈德·法爾杉談話，學習召喚地獄戰馬的能力。"}},
[4491] = {"朋友的幫助", {"把林格帶回馬紹爾營地的斯普拉格·弗勞克身邊。","","如果林格暈倒了，就用斯普拉格的水壺讓他恢復。"}},
[4492] = {"走丟了！", {"在火羽山找到林格。"}},
[4493] = {"異種蠍的行軍", {"與加基森的煉金術士匹斯特蘇格談話。"}},
[4494] = {"異種蠍的遠征", {"與加基森的煉金術士匹斯特蘇格談話。"}},
[4495] = {"好朋友", {"在北邊的洞穴附近找到埃沃隆。"}},
[4496] = {"擒蟲先擒王", {"帶一個Gorishi Scent Gland和5個安戈洛的泥土樣本給加基森的煉金術士匹斯特蘇格。"}},
[4501] = {"當心翼手龍", {"殺掉10隻翼手龍和15隻狂怒的翼手龍，然後向馬紹爾營地的斯普拉格·弗勞克報告。"}},
[4502] = {"火山的活動", {"到安戈洛環形山的火山中去，從那裡的元素身上收集9份安戈洛灰燼，把它們交給棘齒城的莉芙·雷茲菲克斯。"}},
[4503] = {"希茲爾的的飛行器", {"替馬紹爾營地的Shizzle收集8片Webbed Dimetrodon Scales和8片Webbed Pterrordax Scales。"}},
[4504] = {"極度粘稠的瀝青", {"幫加基森的特蘭雷克收集12塊極度粘稠的瀝青。"}},
[4505] = {"腐化之井", {"從碧火薩特的月井中收集一份被腐化的水的樣本，把它交給血毒崗哨的溫娜·哈薩德。"}},
[4506] = {"被腐蝕的貓", {"把溫娜的小貓帶到墮落的月井旁邊，把貓放出來，然後把它還給溫娜。","","當你回到溫娜那裡之後，點擊貓就可以將它還給溫娜。"}},
[4507] = {"小兵捉蠍后", {"當格里什蜂后被召喚之後擊敗她。","","帶格里什皇后的腦袋給加基森的匹斯特蘇格。"}},
