[4864] = {"被激怒的梟獸", {"從雪地中拾起加隆的補給物資，然後尋找加隆所說偷走護符的梟獸。","","將加隆的補給物資和藍色羽毛護符交給冬泉谷的加隆·石矛。"}},
[4865] = {"狂熱之蛇", {"向莫特加·火鬃彙報你的發現。"}},
[4866] = {"蛛后的乳汁", {"你可以在黑石塔的中心地帶找到煙網蛛后。與她戰鬥，讓她在你體內注入毒汁。如果你有能力的話，就殺死她吧。當你中毒之後，回到狼狽不堪的約翰那兒，他會從你的身體裡抽取這些「蛛后的乳汁」。"}},
[4867] = {"烏洛克", {"閱讀瓦羅什的卷軸。將瓦羅什的魔精交給他。"}},
[4881] = {"暗殺計畫", {"將暗殺計畫通知給白沙崗哨的卡納提·灰雲。"}},
[4882] = {"守護秘密", {"把藍羽項鏈交給血毒崗哨的特盧爾·法貝恩。"}},
[4883] = {"守護秘密", {"把藍羽項鏈交給納拉·蠻鬃。"}},
[4903] = {"高圖斯的命令", {"殺死歐莫克大王、指揮官沃恩和維姆薩拉克。找到重要的黑石文件，然後向卡加斯的軍官高圖斯彙報。"}},
[4904] = {"終獲自由", {"護送拉克塔·風歌離開恐怖圖騰營地，然後與亂風崗的薩利亞談話。"}},
[4906] = {"更深重的墮落", {"費伍德森林的艾瑞丹·藍風要你去殺掉8個碧火喚魔者、8個碧火背叛者、8個碧火欺詐者和薩瓦里克。任務完成之後回到艾瑞丹那裡覆命。"}},
[4907] = {"丁奇·斯迪波爾", {"與丁奇·斯迪波爾談話。"}},
[4921] = {"在戰鬥中失蹤", {"找到曼寇里克的妻子，然後回到十字路口找他。"}},
[4961] = {"奧拉赫寶珠的淨化", {"殺死寶珠之魔，然後與塔貝薩談話。"}},
[4962] = {"地獄犬的靈魂", {"帶上地獄犬紅寶石到淒涼之地去，用它捕獲一隻地獄犬的靈魂。成功之後，將地獄犬紅寶石和被禁錮的地獄犬靈魂交給貧瘠之地的梅納拉·沃倫德。"}},
[4963] = {"地獄火的靈魂", {"帶上地獄火綠寶石到淒涼之地去，用它捕獲一個地獄火的靈魂。成功之後，將地獄火綠寶石和被禁錮的地獄火靈魂交給貧瘠之地的梅納拉·沃倫德。"}},
[4964] = {"達奧拉赫寶珠", {"等待梅納拉·沃倫德完成達奧拉赫寶珠，然後再與她談一談。"}},
