[4971] = {"時間問題", {"在安多哈爾的一處倉庫附近使用時光置換器，使時光寄生蟲現身。","","殺掉15隻時光寄生蟲，然後將時光置換器還給西瘟疫之地安多哈爾旅店的克羅米。"}},
[4972] = {"找回時間", {"在安多哈爾城中四處散落的保險箱裡找到5個安多哈爾懷錶，然後把它們交給西瘟疫之地安多哈爾旅店裡的克羅米。"}},
[4973] = {"找回時間", nil},
