[4975] = {"諾奧拉赫寶珠", {"等待梅納拉·沃倫德完成諾奧拉赫寶珠，然後再與她談話。"}},
[4976] = {"歸還淨化過的寶珠", {"將淨化過的地獄火寶珠交給貧瘠之地的梅納拉·沃倫德。"}},
[4981] = {"狡猾的比修", {"到黑石塔去查明比修的下落。"}},
[4982] = {"比修的裝置", {"找到比修的裝置並把它們還給她。你記得她說過她把裝置藏在城市的最底層。"}},
[4984] = {"大自然的苦楚", {"消滅8隻生病的狼，然後去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}},
[4985] = {"大自然的苦楚", {"消滅8隻生病的灰熊，然後去找西瘟疫之地嚎哭鬼屋的穆格雷斯·深水。"}},
[4986] = {"刻著文字的橡木樹枝", {"根據這枝刻著文字的橡木樹枝所附加的魔法，這個牛頭人德魯伊本來準備把它交給達納蘇斯的塞納里奧議會。到那裡去找尋求某個德魯伊的幫助吧。"}},
[4987] = {"刻著文字的橡木樹枝", {"根據這枝刻著文字的橡木樹枝所附加的魔法，這個牛頭人德魯伊本來準備把它交給達納蘇斯的塞納里奧議會。到那裡去找尋求某個德魯伊的幫助吧。"}},
[5021] = {"遲到總比不到好", {"這個女人的幽靈告訴你她要送出一個包裹。她說那個包裹就在她的馬旁邊。至於馬在哪裡或者包裹要送到哪裡去，她卻根本沒有說。"}},
[5022] = {"遲到總比不到好", {"向暴風城的皇家代理人確認艾瑪·費爾斯通的下落。通常在市政廳裡都有一個人口普查官。"}},
[5023] = {"遲到總比不到好", {"與幽暗城的皇家管理人打聽傑雷米亞·費爾斯通的下落。通常在公會註冊處附近會有一個人口普查官。"}},
[5041] = {"十字路口的補給物資", {"找到並把十字路口的補給箱還給貧瘠之地的索克。"}},
