[5045] = {"高漲的士氣", nil},
[5046] = {"野豬之皮", nil},
[5048] = {"善良的艾瑪", {"找到暴風城的老艾瑪並弄清楚她是否就是艾瑪·菲爾斯通。如果她是,那麼她可能會想要珍妮絲·菲爾斯通為她製作的包裹."}},
[5049] = {"傑雷米亞的憂傷", {"在幽暗城找到傑雷米亞·派森並查明他是否真是傑雷米亞·費爾斯通.如果他是，那麼可能他會想要Janice Felstone給他做的包裹。"}},
[5050] = {"好運護符", {"把半個好運護符還給西瘟疫之地的詹妮絲·費爾斯通。"}},
[5051] = {"合二為一", {"在西瘟疫之地的菲爾斯通農場的某個地方找尋另外半個幸運符並組合起來。","","把幸運符交給西瘟疫之地菲爾斯通農場的珍妮絲·菲爾斯通。"}},
[5052] = {"阿迦瑪甘的血岩碎片", {"給陶拉祖營地的碎牙帶去一塊血岩碎片。","","如果你想要他賜予你阿迦瑪甘的力量，就搜集更多的血岩碎片。"}},
[5054] = {"碎齒熊尤西烏斯", {"費伍德森林血毒崗哨的斯托姆·影蹄想要你去殺死尤西烏斯。"}},
[5055] = {"冰風奇美拉布魯米蘭", {"費伍德森林血毒崗哨的斯托姆·影蹄想要你去殺死布魯米蘭。"}},
[5056] = {"希洛塔姆", {"費伍德森林血毒崗哨的斯托姆·影蹄想要你去殺死希洛塔姆。"}},
