[5060] = {"被鎖起來的農夫", nil},
[5061] = {"水棲形態", {"回到達納蘇斯，讓瑪斯雷·馭熊者看看你的海獅墜飾。"}},
[5062] = {"聖火", {"採集10支火岩龍舌蘭，然後去雷霆崖的長者高地尋找瑪加薩·恐怖圖騰。"}},
[5064] = {"偵察恐怖圖騰族", {"在暗雲峰找出並拿回三封秘密訊息。"}},
[5065] = {"失落的摩沙魯石板", {"把第三塊和第四塊摩沙魯石板交給塔納利斯的勘查員詹斯·鐵靴。"}},
[5066] = {"戰鬥的號角：瘟疫之地！", {"找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。"}},
[5082] = {"冬泉熊怪的威脅", {"冬泉谷的多諾瓦·雪山要你去殺死8個冬泉探路者、8個冬泉巢穴守衛和8個冬泉圖騰師。"}},
[5083] = {"冬泉火水", {"將空的火水瓶交給冬泉谷的多諾瓦·雪山。"}},
[5084] = {"墮落熊怪", {"搜尋費伍德森林北部的死木熊怪的營帳，繼續尋找線索。"}},
[5085] = {"神秘的粘液", {"帶著你的發現回去找多諾瓦·雪山。"}},
[5086] = {"劇毒之水", {"為冬泉谷的多諾瓦·雪山收集3份劇毒水滴。"}},
[5087] = {"冬泉信差", {"找到冬泉信差，阻止他們向冬泉村運送物品。"}},
[5088] = {"阿利卡拉", {"殺死阿利卡拉。把她的遺體和火岩粉交給白沙崗哨的莫特加‧火鬃作為證明。"}},
[5090] = {"戰鬥的號角：瘟疫之地！", {"找到指揮官阿胥拉姆·瓦羅菲斯特。他的大本營位於奧特蘭克山脈以北的冰風營地。"}},
