[5092] = {"掃清道路", {"殺掉悔恨嶺中的10個骷髏剝皮者和10個被奴役的食屍鬼。","","然後向西瘟疫之地冰風營地的指揮官阿胥拉姆·瓦羅菲斯特覆命。"}},
[5093] = {"戰鬥的號角：瘟疫之地！", {"找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。"}},
[5094] = {"戰鬥的號角：瘟疫之地！", {"找到高級執行官德靈頓。他將自己的大本營建在提里斯法林地和幽暗城以東的亡靈壁壘。"}},
