[5096] = {"誤導血色十字軍", {"到血色十字軍建在費爾斯通農場和達爾松之淚之間的營地去，摧毀他們的指揮帳篷。","","將天譴軍團的戰旗插在營地中，然後回到西瘟疫之地亡靈壁壘的高級執行官德靈頓那兒。"}},
[5097] = {"標記哨塔", {"使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。","","在做完了標記之後，將信號火炬還給西瘟疫之地冰風營地的指揮官阿胥拉姆·瓦羅菲斯特。"}},
[5098] = {"標記哨塔", {"使用信號火炬為安多哈爾城中的四座哨塔做上標記，你必須站在哨塔門口才能成功地進行標記。","","在做完了標記之後，將信號火炬還給西瘟疫之地亡靈壁壘的高級執行官德靈頓。"}},
[5102] = {"達基薩斯將軍之死", {"去黑石塔殺掉達基薩斯將軍。當任務完成之後回去找麥斯威爾指揮官。"}},
