[5128] = {"熊怪酋長的話", {"將潦草的日誌交給費伍德森林南部的科雷克·望天。"}},
[5141] = {"龍鱗製皮", nil},
[5142] = {"小潘蜜拉", {"找尋潘蜜拉·雷德帕斯。"}},
[5143] = {"部族製皮", {"將1件蠻皮外衣和1件蠻皮頭盔交給菲拉斯的凱雷希亞·獵月。","","完成這項任務之後，你就可以學到部族製皮技術了。","","同時，你也將永遠無法學習元素製皮技術和龍鱗製皮技術，在決定之前先考慮清楚。"}},
