[5147] = {"通緝：阿納克‧恐怖圖騰", {"殺死阿納克·恐怖圖騰，並向亂風崗的峭壁衛兵圖林·長角出示證據。"}},
[5149] = {"帕米拉的洋娃娃", {"找到帕米拉的洋娃娃。"}},
[5150] = {"達丹加餓了！", nil},
[5151] = {"超適應齒輪", {"殺了那隻野獸並把超適應齒輪和豹籠鑰匙帶回來交給維茲羅。"}},
[5152] = {"瑪萊恩姑媽", {"與安多哈爾廢墟南邊的瑪萊恩談話。"}},
[5153] = {"古怪的歷史學家", {"把約瑟夫的結婚戒指交給安多哈爾的克羅米。"}},
[5154] = {"達隆郡的歷史", {"把《達隆郡的歷史》交給安多哈爾的克羅米。"}},
[5155] = {"加德納爾的勢力", {"到加德納爾去殺掉4個加德納爾惡犬、4個加德納爾守護者、6個加德納爾精兵和6個加德納爾祭司，然後向費伍德森林的格雷塔·苔蹄覆命。"}},
[5156] = {"驗證腐蝕", {"殺掉2個熱能野獸和2個熱能恐獸，並探索碎痕谷。然後查看凹坑中是否仍然充滿了墮落的惡臭之水，完成這些任務之後，向費伍德森林中的塔諾恩·紅羽覆命。"}},
[5157] = {"收集墮落之水", {"把空壺拿到加德納爾中心的月井去，裝滿井水之後再回到費伍德森林的格雷塔·苔蹄那裡。"}},
[5158] = {"水之魂的幫助", {"把腐化的月井水交給貧瘠之地的水之先知伊斯倫。"}},
[5159] = {"淨化過的水", {"把淨化過的月井水交給費伍德森林的格雷塔·苔蹄。"}},
[5163] = {"雪怪計畫！", {"帶著烏米的機械雪人去嚇唬她的朋友：","","永望鎮的萊加奇（冬泉谷）、加基森的斯普琳科（塔納利斯），還有馬紹爾營地的奎克希爾（安戈洛環形山）。","","當你完成任務之後，把機械雪人還給烏米。"}},
[5165] = {"熄滅火焰", {"使用淨化過的月井水熄滅暗影堡內部的四座火盆的火焰，從而破除其保護效果，然後向翡翠聖地的格雷塔·苔蹄覆命。"}},
[5168] = {"達隆郡的英雄", {"把達維的聖契和雷德帕斯之盾交給卡林·雷德帕斯。"}},
[5181] = {"達隆郡的惡魔", {"將霍古斯的顱骨和馬杜克的破碎之劍交給聖光之願禮拜堂的卡林·雷德帕斯。"}},
[5202] = {"奇怪的紅鑰匙", {"搜尋加德納爾，找出血紅鑰匙的用途。"}},
[5203] = {"逃出加德納爾", {"護送亞科納琳到萊弗治和她的裝備所在的地方，然後保護她逃離暗影堡。之後，在費伍德森林找傑希爾·月弓，並告訴她剛才發生的事情。"}},
[5204] = {"光明的懲戒", {"回到加德納爾殺了魅魔拉凱雅，然後找到特雷·萊弗治的殘骸。"}},
[5206] = {"達隆郡的掠奪者", {"把5個共鳴顱骨和神秘水晶交給東瘟疫之地的卡林·雷德帕斯。"}},
[5210] = {"卡林·雷德帕斯", {"將《達隆鎮全史》交給東瘟疫之地的卡林·雷德帕斯。"}},
[5211] = {"達隆郡的保衛者", {"釋放15個達隆郡居民的靈魂，然後返回卡林·雷德帕斯身邊。"}},
[5212] = {"血肉不會撒謊", {"從斯坦索姆找回20個瘟疫肉塊，並把它們交給貝蒂娜·比格辛克。你覺得斯坦索姆中的生物都不大可能長著肉。"}},
[5213] = {"活躍的探子", {"到斯坦索姆去探索那裡的通靈塔。找到新的天譴軍團檔案，把它交給貝蒂娜·比格辛克。"}},
[5214] = {"偉大的艾茲拉‧格里姆", {"找到艾茲拉‧格里姆在斯坦索姆的煙草店，並從中找回一盒格里姆的特級煙草，把它交給煙鬼拉魯恩。"}},
