[5216] = {"目標：費爾斯通農場", {"到西瘟疫之地的費爾斯通農場去，找到並擊敗那裡的護鍋者，用它的鑰匙打開瘟疫之鍋。你必須隨身攜帶費爾斯通農場的空瓶來採集瘟疫之鍋中的毒藥樣本。"}},
