[5243] = {"神聖之屋", {"到北方的斯坦索姆去，尋找散落在城市中的補給箱，並收集5瓶斯坦索姆聖水。當你找到足夠的聖水之後就回去向萊尼德·巴薩羅梅覆命。"}},
