[5245] = {"凱斯利爾的怨靈", {"使用加隆的鎬來尋找四塊精靈貴族聖物的碎片，把它們交給東瘟疫之地的奧蘿拉。"}},
[5246] = {"歷史的殘片", {"在艾薩拉的辛瑪洛神殿裡，找到神聖的精靈貴族筆跡。然後交給奧蘿拉，她就靠近東瘟疫之地的北地哨塔。"}},
[5247] = {"歷史的殘片", {"給接近東瘟疫之地的奧蘿拉帶1塊附魔瑟銀錠、5塊恢復水晶，以及1小瓶恐怖之水。"}},
[5249] = {"前往冬泉谷！", {"找到冬泉谷的墜星村，在那裡與威恩德·夜風談話。"}},
