[5261] = {"伊根·派特斯金納", {"與伊根·派特斯金納談話。"}},
[5262] = {"可怕的真相", {"將巴納札爾的頭顱交給東瘟疫之地的尼古拉斯·瑟倫霍夫公爵。"}},
[5263] = {"超越", {"到斯坦索姆去殺掉瑞文戴爾男爵，把他的頭顱交給尼古拉斯·瑟倫霍夫公爵。"}},
[5281] = {"永不安息的靈魂", {"找到伊根。你只知道他在斯坦索姆附近。"}},
[5282] = {"永不安息的靈魂", {"對斯坦索姆的鬼魂使用伊根的衝擊器。當那些永不安息的靈魂掙脫他們的外殼時，再次使用伊根的衝擊器——他們就可以獲得自由了！","","解放15個永不安息的靈魂，然後回到伊根那裡去。"}},
[5283] = {"護甲鍛造師的藝術", {"要想成為一名護甲鑄造師的話，你必須將下列物品交給格魯努斯：4頂華麗秘銀頭盔、2雙華麗秘銀戰靴和1副華麗秘銀胸甲。"}},
[5284] = {"武器鑄造師之道", {"要想成為一名武器鑄造師的話，你必須將下列物品交給埃隆努斯·冷鋼：4把月鋼寬劍、4把巨型鐵斧、2把秘銀重斧和2把巨型黑色錘。"}},
[5301] = {"護甲鍛造師的藝術", {"要想成為一名護甲鍛造師的話，你必須將下列物品交給奧克索斯：4頂華麗秘銀頭盔、2雙華麗秘銀戰靴和1副華麗秘銀胸甲。"}},
[5302] = {"武器鑄造師之道", {"要想成為一名武器鑄造師的話，你必須將下列物品交給伯古什：4把月鋼寬劍、4把巨型鐵斧、2把秘銀重斧和2把巨型黑色錘。"}},
[5321] = {"昏昏欲睡", {"護送克羅尼亞‧恒影沿著道路向南前往利拉迪斯‧月河那裡，並在黑海岸尋找他的背包。"}},
[5341] = {"巴羅夫家族的寶藏", {"到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到阿萊克斯·巴羅夫那兒去。"}},
[5342] = {"巴羅夫的繼承人", {"到冰風營地——聯盟的領地——去暗殺維爾頓·巴羅夫。把他的腦袋交給阿萊克斯·巴羅夫。","","要多加小心，聯盟也許對維爾頓執行了嚴密的保護。"}},
[5343] = {"巴羅夫家族的寶藏", {"到通靈學院中去取得巴羅夫家族的寶藏。這份寶藏包括四份地契：凱爾達隆地契、布瑞爾地契、塔倫米爾地契，還有南海鎮地契。完成任務之後就回到維爾頓·巴羅夫那兒去。"}},
[5361] = {"族譜", {"將峭壁衛兵圖林·長角的報告交給淒涼之地鬼旅崗哨的納塔卡·長角。"}},
[5381] = {"埃盧梭斯之手", {"在雷斧堡壘中找到惡魔之盒，把它和惡魔之鋤一起交給葬影村的泰迦·慧鬃。"}},
[5382] = {"瑟爾林·卡斯迪諾夫教授", {"在通靈學院中找到瑟爾林·卡斯迪諾夫教授。殺死他，並燒毀艾瓦·薩克霍夫和盧森·薩克霍夫的遺體。任務完成後就回到艾瓦·薩克霍夫那兒。"}},
[5384] = {"傳令官基爾圖諾斯", {"帶著無辜者之血回到通靈學院，將它放在門廊的火盆下方，基爾圖諾斯會前來吞噬你的靈魂。","","勇敢地戰鬥吧，不要退縮！殺死基爾圖諾斯，然後回到艾瓦·薩克霍夫那兒。"}},
[5385] = {"特雷·萊弗治的殘骸", {"將特雷·萊弗治的殘骸交給費伍德森林的傑希爾·月弓。"}},
[5386] = {"食魚度日", {"與葬影村的吉納澤林談話，然後將2條血肚魚交給納塔卡·長角。"}},
[5401] = {"銀色黎明委任徽章", nil},
[5402] = {"爪牙的天譴石", nil},
[5403] = {"侵略者的天譴石", nil},
[5404] = {"墮落者的天譴石", nil},
[5405] = {"銀色黎明委任徽章", nil},
[5406] = {"墮落者的天譴石", nil},
[5407] = {"侵略者的天譴石", nil},
[5408] = {"爪牙的天譴石", nil},
[5421] = {"坐享其成", nil},
[5441] = {"懶惰的苦工", {"在懶惰的苦工睡覺時，用工頭的木棒敲他們。敲醒5個苦工，然後把工頭的木棒還給試煉谷的工頭塔茲利爾。"}},
[5461] = {"萊斯·霜語", {"到阿拉希高地的激流堡遺跡裡面尋找巫妖生前的遺物。如果你能找到這樣的東西，就把它交給馬杜克鎮長。"}},
[5462] = {"亡靈萊斯·霜語", {"到東瘟疫之地的聖光之願禮拜堂去找到萊尼德·巴薩羅梅，給他看看巫妖生前的遺物，並告訴他你收集到的情報。"}},
[5463] = {"米奈希爾的禮物", {"到斯坦索姆城裡去找到米奈希爾的禮物，把巫妖生前的遺物放在那塊邪惡的土地上。"}},
[5481] = {"葛爾多的任務", {"收集3根陰暗草，把它們交給布瑞爾墓地的初級藥劑師霍蘭德。"}},
[5482] = {"末日草", {"收集10株末日草，把它們交給初級藥劑師霍蘭德。"}},
[5501] = {"集骨者", {"從科多墓地收集10根科多獸骨，把它們交給獸人小屋的比布里·弗斯巴克。"}},
[5508] = {"墮落者的天譴石", nil},
[5509] = {"侵略者的天譴石", nil},
[5510] = {"爪牙的天譴石", nil},
[5514] = {"昂貴的模具", {"把灌魔的骸骨碎片和15枚金幣交給加基森的克林科·古德斯迪爾。"}},
[5515] = {"卡斯迪諾夫的恐懼之袋", {"在通靈學院找到詹迪斯·巴羅夫並打敗她。從她的屍體上找到卡斯迪諾夫的恐懼之袋，然後將其交給艾瓦·薩克霍夫。"}},
[5518] = {"戈多克巨魔裝", {"把4份符文布卷、8塊硬甲皮、2卷符文線和一份巨魔鞣酸交給諾特·希姆加克。他現在被拴在厄運之槌的戈多克巨魔那邊。"}},
[5527] = {"淨化之匣", {"到希利蘇斯的南風村去尋找淨化之匣。然後將其交給月光林地永夜港的拉比恩·薩圖納。"}},
[5529] = {"瘟疫之龍", {"殺掉20隻瘟疫幼龍，然後向聖光之願禮拜堂的貝蒂娜·比格辛克復命。"}},
[5533] = {"通靈學院", {"和西瘟疫之地冰風崗的化學家阿爾比頓談話。"}},
[5534] = {"基姆加爾「丟失」的裝備", {"尋找埃達拉斯廢墟中的納迦攜帶的那些符石，然後把它們交給艾薩拉的基姆加爾。"}},
[5535] = {"永不安息的靈魂", {"殺掉6個精靈貴族的幻影和6個精靈貴族鬼巫，然後向艾薩拉的羅哈圖覆命。"}},
[5536] = {"充滿仇恨的土地", {"殺掉6個哈達爾薩特、2個哈達爾欺詐者和2個哈達爾魔僕，然後向梣谷與艾薩拉交界處的羅哈圖覆命。"}},
[5537] = {"骸骨碎片", {"將15塊骷髏碎片交給西瘟疫之地冰風崗的化學家阿爾比頓。"}},
[5538] = {"昂貴的模具", {"把灌魔的骸骨碎片和15枚金幣交給加基森的克林科·古德斯迪爾。"}},
[5541] = {"海格納的彈藥", {"把海格納的彈藥交給丹莫洛的海格納·重槍。"}},
[5542] = {"惡魔之犬", {"殺掉20條瘟疫幼犬、5條瘟疫犬和5條狂怒的瘟疫犬。任務完成之後向提里恩·弗丁覆命。"}},
[5543] = {"血染的天空", {"殺死30隻瘟疫蝙蝠，然後向提里恩·弗丁覆命。"}},
[5544] = {"腐肉蟲", {"在東瘟疫之地搜索腐肉蟲和腐肉吞噬者。殺了它們並收集它們的肉。當你收集到15塊食腐蟲肉塊之後，就回到提里恩·弗丁那裡。"}},
[5545] = {"木材危機", {"收集8捆木材，把它們交給東谷伐木場的管理員萊琳。"}},
[5561] = {"誘捕科多獸", {"將科多獸誘引器和5頭被馴服的科多獸交給瑟卡布斯庫的營地中的斯米德·瑟卡布斯庫。"}},
[5581] = {"燃燒軍團的傳送門", {"放逐6個瑪諾洛克集會所的傳送門，然後回到葬影村的泰迦·慧鬃那裡。"}},
[5582] = {"健康的龍鱗", {"把健康的龍鱗交給東瘟疫之地聖光之願禮拜堂中的貝蒂娜·比格辛克。"}},
[5601] = {"小妹妹帕米拉", {"在達隆郡裡找到帕米拉·雷德帕斯。"}},
[5621] = {"月光之衣", {"找到哨兵莎恩雅並使用次級治療術（等級 2）來治療她。然後對她施放真言術：韌，最後向多蘭納爾的勞爾娜·晨光覆命。"}},
[5622] = {"月神的恩賜", {"與泰達希爾的勞爾娜·晨光談話。"}},
[5623] = {"聖光的恩賜", {"與艾爾文森林的女牧師潔塞塔談話。"}},
[5624] = {"聖光之衣", {"找到衛兵羅伯茲並使用次級治療術（等級 2）治療他。然後對他施放真言術：韌，之後回來找閃金鎮的女牧師潔塞塔。"}},
[5625] = {"聖光之衣", {"找到巡山人多爾夫並使用次級治療術（等級 2）治療他。然後對他施放真言術：韌，之後回去找卡拉諾斯的馬克薩恩·安沃爾。"}},
[5626] = {"聖光的恩賜", {"與丹莫洛的馬克薩恩·安沃爾談話。"}},
[5627] = {"伊露恩之星", nil},
[5635] = {"絕望禱言", {"與鐵爐堡的高階牧師洛漢交談。"}},
[5641] = {"譴責", nil},
[5646] = {"黑暗獻祭", {"與幽暗城的艾薩萊斯特談話。"}},
[5654] = {"虛弱妖術", {"與奧格瑪的烏爾庫談話。"}},
[5658] = {"虛弱之觸", nil},
[5673] = {"伊露恩的賜福", {"與達納蘇斯的女祭司阿蘭希雅談話。"}},
[5676] = {"秘法回饋", nil},
[5679] = {"黑暗獻祭", nil},
[5713] = {"見一個殺一個", {"保護哨兵阿娜莎，然後向梣谷邁斯特拉崗哨的奧奈雅報告。"}},
[5721] = {"達隆郡的戰鬥", {"將聖物包裹放在達隆郡的廣場中。","","在霍古斯死亡之前，達維必須存活。","","在雷德帕斯隊長墮落之前保證他存活。","","擊敗墮落的雷德帕斯。","","當約瑟夫·雷德帕斯出現在廣場中時，與他的靈魂進行交談，然後回到帕米拉的家中去找帕米拉。"}},
[5722] = {"尋找背包", {"在怒焰裂谷搜尋瑪爾·恐怖圖騰的屍體以及他留下的東西。"}},
[5723] = {"試探敵人", {"在奧格瑪找到怒焰裂谷，殺掉8個怒焰穴居怪和8個怒焰薩滿，然後向雷霆崖的拉哈羅覆命。"}},
[5724] = {"歸還背包", {"將恐怖圖騰背包交給雷霆崖的拉哈羅。"}},
[5725] = {"毀滅之力", {"將《暗影法術研究》和《扭曲虛空的魔法》這兩本書交給幽暗城的瓦里瑪薩斯。"}},
[5726] = {"隱藏的敵人", {"將軍官的徽章交給奧格瑪的索爾。"}},
[5727] = {"隱藏的敵人", {"將軍官的徽章交給尼爾魯·燃刃並與他談話，看看他是否相信你是燃刃氏族中的一員，然後回到奧格瑪的索爾那裡。"}},
[5728] = {"隱藏的敵人", {"殺死巴札蘭和祈求者耶戈什，然後回到奧格瑪的索爾那裡。"}},
[5729] = {"隱藏的敵人", {"與奧格瑪的尼爾魯·火刃談話。"}},
[5730] = {"隱藏的敵人", {"與奧格瑪的索爾談話，告訴他你瞭解到的東西。"}},
[5741] = {"聖光節杖", {"拿到聖光節杖，並將它交給艾瑟雷索塔里的阿佐爾·奧達蒙特。"}},
[5742] = {"救贖", {"聽聽提里恩·弗丁要說什麼。"}},
[5761] = {"饑餓者塔拉加曼", {"進入怒焰裂谷，殺死饑餓者塔拉加曼，然後把他的心臟交給奧格瑪的尼爾魯·火刃。"}},
[5762] = {"赫米特·奈辛瓦里", {"將克拉維爾的箱子送到荊棘谷的赫米特·奈辛瓦里那裡。"}},
[5763] = {"荊棘谷狩獵", {"將魯恩的科多獸角送到荊棘谷的赫米特·奈辛瓦里那裡。"}},
[5781] = {"遺忘的記憶", {"到東瘟疫之地最南端的墓室去找回泰蘭之錘。完成目標之後，返回提里恩·弗丁那裡。"}},
[5801] = {"火羽山", {"把骷髏鑰匙模具和2塊瑟銀錠帶到安戈洛環形山地區的火羽山頂部。在熔岩湖旁使用骷髏鑰匙模具，鑄造出一把未完工的骷髏鑰匙。","","把未完工的骷髏鑰匙交給西瘟疫之地冰風崗的化學家阿爾比頓。"}},
[5802] = {"火羽山", {"把骷髏鑰匙模具和2塊瑟銀錠帶到安戈洛環形山地區的火羽山頂部。在熔岩湖旁使用骷髏鑰匙模具，鑄造出一把未完工的骷髏鑰匙。","","把未完工的骷髏鑰匙交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。"}},
[5804] = {"阿拉基的聖甲蟲", {"摧毀安多哈爾的4顆天災召喚水晶來召喚阿拉基。殺掉召喚者阿拉基，並將阿拉基的聖甲蟲交給西瘟疫之地亡靈壁壘的藥劑師迪瑟斯。"}},
[5821] = {"雇傭保鏢", {"護送基澤爾頓商隊通過科卡爾半人馬村，然後與瑟卡布斯庫的營地中的斯米德談話以領取你的獎賞。"}},
[5845] = {"失落的榮耀", {"到東瘟疫之地東北部的北谷去，找到失落榮耀的象徵。完成目標之後向提里恩·弗丁覆命。"}},
[5846] = {"愛與家庭", {"到凱爾達隆島去，尋找關於那副畫的線索。凱爾達隆島在瘟疫之地南部的湖中央。"}},
[5848] = {"愛與家庭", {"到瘟疫之地北部的斯坦索姆去。你可以在血色十字軍堡壘中找到「愛與家庭」這幅畫，它被隱藏在另一幅描繪兩個月亮的畫之後。","","把這幅畫還給提里恩·弗丁。"}},
[5861] = {"尋找米蘭達", {"到瘟疫之地南部的烏瑟之墓去，將提里恩的禮物交給巫女米蘭達。"}},
[5862] = {"血色幻象", {"和巫女米蘭達交談以獲得血色幻象的效果。在血色幻象的掩護下深入壁爐谷，將提里恩的禮物交給大領主泰蘭·弗丁。","","壁爐谷在北方，泰蘭應該在瑪登霍爾德城堡裡面。"}},
[5863] = {"砂槌巨魔", {"加基森的安迪·利恩想要你攻入砂槌營地，殺死10個砂槌蠻兵、10個砂槌執行者，以及掠奪者格瑪洛克。"}},
[5881] = {"召回衛兵", {"馬格蘭希望你將信送到貧瘠之地升降梯的瑞什·遠行者手中。"}},
[5882] = {"狩獵換藥膏", nil},
[5885] = {"剝皮換藥膏", nil},
[5887] = {"狩獵換藥膏", nil},
[5888] = {"採礦換藥膏", nil},
[5890] = {"剝皮換藥膏", nil},
[5901] = {"瘟疫與你", {"在東瘟疫之地的蟻丘上使用空的白蟻瓶。當你收集了100隻瘟疫白蟻之後，就回到提里斯法林地的亡靈壁壘去找米克·萊文。"}},
[5902] = {"瘟疫與你", {"到西瘟疫之地的北山伐木場去找個合適的地方，在那裡放下一桶瘟疫白蟻。"}},
[5903] = {"瘟疫與你", {"在東瘟疫之地的蟻丘上使用空的白蟻瓶。當你收集了100隻瘟疫白蟻之後，就回到西瘟疫之地的冰風營地去找納薩尼爾·杜馬。"}},
[5904] = {"瘟疫與你", {"到西瘟疫之地的北山伐木場去找個合適的地方，在那裡放下一桶瘟疫白蟻。"}},
[5921] = {"月光林地", {"使用法術「傳送：月光林地」抵達月光林地，在那裡與永夜港的德迪利特·星焰談話。"}},
[5923] = {"回應召喚", {"與達納蘇斯塞納里奧區的瑪斯雷·馭熊者談話。"}},
[5925] = {"回應召喚", {"與達納蘇斯塞納里奧區的瑪斯雷·馭熊者談話。"}},
[5929] = {"巨熊之靈", {"到月光林地的西北部去尋找巨熊之靈，向它學習關於熊的知識，然後回到月光林地的永夜港去找德迪利特·星焰。"}},
[5931] = {"返回達納蘇斯", {"回到達納蘇斯，與塞納里奧區的瑪斯雷·馭熊者談話。"}},
[5941] = {"返回克羅米身邊", {"將一包聖物交給安多哈爾的克羅米。"}},
[5943] = {"基澤爾頓車隊", {"護送基澤爾頓車隊通過瑪諾洛克集會所，然後與瑟卡布斯庫的營地的斯米德談一談，領取你的獎勵。"}},
[5961] = {"女妖之王的勇士", {"與東瘟疫之地的納薩諾斯·凋零者談一談。據說他居住在瑪瑞斯農場。"}},
[6001] = {"身心之力", {"使用奧伯丁的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。","","任務完成之後，與達納蘇斯的瑪斯雷·馭熊者談話。"}},
[6002] = {"身心之力", {"使用莫高雷與貧瘠之地交界處的月夜梟獸之石上面的塞納里奧月塵引出月爪梟獸，然後擊敗月爪梟獸並吸取它所擁有的身心之力。","","任務完成之後，與雷霆崖的圖拉克·符文圖騰談話。"}},
[6004] = {"未竟的事業", {"殺死2個血色醫護員、2個血色獵人、2個血色魔法師和2個血色騎士，然後回到西瘟疫之地的科爾斯塔·迪普沙東那兒。"}},
[6021] = {"流亡者塞達爾", {"將塞達爾的頭顱交給聖光之願禮拜堂的護理者奧林。"}},
[6022] = {"殺戮的理由", {"到東邊的考林路口去屠殺鎮裡的天譴軍團。在10分鐘內收集7塊生命腐質，使用研缽和搗杵將其研磨成凝固腐質。"}},
[6023] = {"未完的任務", {"殺掉獵人萊德雷和騎士杜爾根，然後向西瘟疫之地的科爾斯塔·迪普沙東覆命。"}},
[6024] = {"哈米亞的請求", {"殺了滲透者哈米亞，用他的鑰匙開啟墓室後的一堆泥土。"}},
[6025] = {"未完的任務", {"進入壁爐谷並找一處高地，你可以在那裡觀察整個城鎮並估算血色十字軍的兵力，然後向西瘟疫之地的科爾斯塔·迪普沙東回報。"}},
[6026] = {"獅子大開口", {"煙鬼拉魯恩要你拿來2塊瑟銀錠、1根金棒、8顆高爆炸彈和8個不牢固的扳機。","","你需要找鐵匠和工程學技師幫忙製作這些東西。"}},
[6027] = {"上古之書", {"拿到上古之書，將其交給艾瑟雷索塔中的阿佐爾·奧達蒙特。"}},
[6028] = {"永望鎮報告", {"把永望鎮報告送給西瘟疫地冰風營地的銀色黎明軍官普爾哈特。"}},
[6029] = {"永望鎮報告", {"把永望鎮報告送給西瘟疫地亡靈壁壘的銀色黎明軍官加魯什。"}},
[6030] = {"尼古拉斯·瑟倫霍夫公爵", {"將《靈語研究》這本書交給東瘟疫之地聖光之願禮拜堂的尼古拉斯·瑟倫霍夫公爵。"}},
[6041] = {"煙鬼的炸藥", {"到聖光之願禮拜堂西北方的病木林去。在那些有爆炸標記的建築物中對爆炸標記使用煙鬼的特殊混合物，以此來摧毀8座天譴軍團建築。煙鬼已經給通靈塔和屠宰房做上了標記。","","一旦你放置好炸彈，就離那些建築物遠一些，然後盡情欣賞你的傑作吧。","","順便說一句，煙鬼的特殊混合物相當...不穩定。"}},
[6042] = {"討厭的蝙蝠", {"殺掉20隻毒性瘟疫蝙蝠和10隻巨型瘟疫蝙蝠，然後回到納薩諾斯·凋零者那裡。"}},
[6062] = {"馴服野獸", {"使用馴獸棒馴服可怕的雜斑野豬。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。"}},
[6063] = {"馴服野獸", {"使用馴獸棒馴服樹林潛伏者。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。"}},
[6064] = {"馴服野獸", {"使用馴獸棒馴服大型峭壁野豬。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。"}},
[6068] = {"獵人之道", {"與剃刀嶺的索塔爾談話。"}},
[6069] = {"獵人之道", {"與剃刀嶺的索塔爾談話。"}},
[6071] = {"獵人之道", {"與多蘭納爾的達札拉談話。"}},
[6075] = {"獵人之道", {"與卡拉諾斯的格瑞夫談話。"}},
[6081] = {"訓練野獸", {"與奧格瑪的奧瑪克談話。"}},
[6082] = {"馴服野獸", {"使用馴獸棒馴服硬甲蠍。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。"}},
[6083] = {"馴服野獸", {"使用馴獸棒馴服海浪蟹。練習你的技能，然後將馴獸棒還給剃刀嶺的索塔爾。"}},
[6084] = {"馴服野獸", {"使用馴獸棒馴服雪豹。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。"}},
[6085] = {"馴服野獸", {"使用馴服獸棒馴服一頭冰爪熊。練習你的技能，然後將馴獸棒還給卡拉諾斯的格瑞夫。"}},
[6086] = {"訓練野獸", {"與鐵爐堡的貝莉亞·雷岩談話。"}},
[6101] = {"馴服野獸", {"使用馴獸棒馴服一隻夜刃捕食者。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。"}},
[6102] = {"馴服野獸", {"使用馴獸棒馴服一隻巨翼惡梟。練習你的技能，然後將馴獸棒還給多蘭納爾的達札拉。"}},
[6103] = {"訓練野獸", {"與達納蘇斯塞納里奧區的祖卡斯特談話。"}},
[6121] = {"新的課程", {"到月光林地去，與永夜港的德迪利特·星焰談話。"}},
[6122] = {"毒水之源", {"使用空的峭壁之泉取樣器在瀑布洞口獲得水樣本。","","將盛滿的峭壁之泉取樣器送到黑海岸奧伯丁的奧蘭達利亞·夜歌那裡。"}},
[6123] = {"收集解藥", {"收集5個地根草和12個月亮菇，把它們交給奧伯丁的奧蘭達利亞·夜歌，這樣她就可以製作解藥了。"}},
[6124] = {"消除疾病", {"對黑海岸的10頭生病的鹿使用動物醫療藥膏，以此來治療它們。從壁泉河到奧伯丁，直到最南端靠近梣谷的地區都有生病的鹿出沒。"}},
[6125] = {"解毒之術", {"回到達納蘇斯塞納里奧區的瑪斯雷·馭熊者那裡。"}},
[6126] = {"新的課程", {"到月光林地去，與永夜港的德迪利特·星焰談話。"}},
[6127] = {"毒水之源", {"使用空的鬼霧峰取樣器在山頂取水樣。","","將盛滿的鬼霧峰取樣器送到貧瘠之地十字路口的圖加·符文圖騰那裡。"}},
[6128] = {"收集解藥", {"收集5個地根草和5個科多獸角，把它們交給十字路口的圖加·符文圖騰，這樣他就可以製作解藥了。"}},
[6129] = {"消除疾病", {"對貧瘠之地北部的10隻生病的瞪羚使用動物醫療藥膏，以此來治療它們。在穿過十字路口的那條東西走向的大路北面到處都是生病的蹬羚。"}},
[6130] = {"解毒之術", {"回到雷霆崖長者高地的圖拉克·符文圖騰那裡。"}},
[6132] = {"救我出去！", {"護送梅麗薩，再到淒涼之地和科多獸墳場的霍恩尼茲談談。"}},
[6133] = {"遊俠之王的命令", {"到東瘟疫之地的北方邊界去找回奎爾薩拉斯名冊，這件物品在奎爾林斯小屋的某處。","","另外你還必須殺掉8個遊俠、8個巡路者和8個護林者。"}},
[6134] = {"幽靈電漿", {"把8個幽靈電漿和幽靈磁鐵箱帶給淒涼之地的霍恩尼茲。"}},
[6135] = {"暗翼蝠", {"找到暗翼蝠並殺掉它。從屍體上取下一塊暗翼蝠的皮，並把它交給納薩諾斯·凋零者。","","據說暗翼蝠遊蕩在瑪瑞斯農場北面的荒原上。"}},
[6136] = {"肥仔", {"找到東部瘟疫之地的北方荒原中的淤血蟲並消滅它。任務完成後回去找納薩諾斯·凋零者。"}},
[6141] = {"安東修士", {"與淒涼之地的安東修士談話。"}},
[6142] = {"蚌肉魚餌", {"找到10塊軟殼蚌肉，把它們交給葬影村的麥拉斯。"}},
[6143] = {"另一種魚", {"殺死7個滑刃侍從、7個滑刃納迦，以及5個滑刃巫師，然後與葬影村的杜澤加爾談談。"}},
[6144] = {"上級的命令", {"到幽暗城去與瓦里瑪薩斯談話。"}},
[6161] = {"拉克摩爾的財寶！", {"找到拉克摩爾的銀鑰匙和金鑰匙。找到並打開拉克摩爾的箱子。"}},
[6162] = {"最後一戰", {"殺死主宰洛爾，把他的爪子交給費伍德森林血毒崗哨的德雷卡蘇。"}},
[6164] = {"奧古斯圖斯的帳本", {"把奧古斯圖斯的帳本交給恐懼谷中精神失常的奧古斯圖斯。"}},
[6181] = {"快遞消息", {"將路易斯的便箋交給獅鷲獸管理員索爾。"}},
[6182] = {"第一個和最後一個", {"與暴風城的馬迪亞斯·肖爾談一談，他住在舊城區的兵營裡。"}},
[6183] = {"逝者的榮耀", {"如果你願意接這個任務，就再和馬迪亞斯·肖爾談話。"}},
[6184] = {"弗林特·沙多摩爾", {"到西瘟疫之地的冰風營地去跟弗林特·沙多摩爾會面。"}},
[6185] = {"東部的瘟疫", {"搜尋東瘟疫之地，尋找「凋零者」的線索以及失蹤的軍情七處密探。如果你找到任何軍情七處徽章，就把它們交給冰風營地的弗林特·沙多摩爾。"}},
[6186] = {"凋零者", {"回到暴風城，將納薩諾斯·瑪瑞斯的下落報告給伯瓦爾·弗塔根公爵。"}},
[6187] = {"重鑄秩序", {"組織一支部隊，然後到東瘟疫之地去。向納薩諾斯·凋零者和任何敢於保護他的部落成員發起攻擊。","","你要傾盡全力，<name>。部落會不惜一切代價保護他們的遊俠領主。"}},
[6261] = {"杜加爾·朗德瑞克", {"將奧斯瑞克的箱子交給獅鷲獸管理員杜加爾·朗德瑞克。"}},
[6281] = {"趕赴暴風城", {"從獅鷲獸管理員索爾那裡租用一頭獅鷲獸，然後把路易斯的便箋交給暴風城有限防護的奧斯瑞克·斯圖恩。"}},
[6282] = {"鷹身人的威脅", {"烈日石居的馬格蘭要你去殺掉7個血怒鷹身人、7個血怒伏擊者、7個血怒殺戮者和7個血怒遊蕩者。"}},
[6283] = {"血怒一族", {"烈日石居的馬格蘭要你去殺掉血怒撕裂者，然後把她的遺體帶回來作為證據。"}},
[6284] = {"貝瑟萊斯", {"殺掉貝瑟萊斯，然後把貝瑟萊斯的牙齒交給烈日石居的馬格蘭。"}},
[6285] = {"返回西部荒野", {"從獅鷲獸管理員杜加爾·朗德瑞克那裡租用一頭獅鷲獸飛到哨兵嶺，然後將奧斯瑞克的箱子交給哨兵嶺的路易斯。"}},
[6301] = {"生生不息", {"烈日石居的塔姆拉·荒原要你去收集10枚蓋亞之種。"}},
[6321] = {"瑟伯切爾的補給", {"將博迪瑞格的訂單交給卡洛斯·拉佐克。"}},
[6322] = {"邁克爾·加勒特", {"將高頓的箱子交給邁克爾·加勒特。"}},
[6323] = {"飛往幽暗城", {"從蝙蝠管理員卡洛斯·拉佐克那裡租一隻蝙蝠飛往幽暗城，然後將博迪瑞格的訂單交給幽暗城裡的高頓·溫德哈姆。"}},
[6324] = {"向博迪瑞格回報", {"從蝙蝠管理員邁克爾·加勒特那兒租一隻蝙蝠飛往瑟伯切爾，然後將高頓的箱子交給瑟伯切爾的亡靈衛兵博迪瑞格。"}},
[6341] = {"泰達希爾的漁業", {"將尼莎的貨物交給維斯派塔斯。"}},
[6342] = {"飛往奧伯丁", {"從角鷹獸管理員維斯派塔斯那裡乘角鷹獸到奧伯丁，然後將尼莎的貨物交給賴爾德。"}},
[6343] = {"飛回泰達希爾", {"將賴爾德的回信交給尼莎·影歌。"}},
[6344] = {"尼莎·影歌", {"與尼莎·影歌談話。"}},
[6361] = {"一捆獸皮", {"帶著獸皮去找十字路口的雙足飛龍管理員迪弗拉克。"}},
[6362] = {"飛往雷霆崖", {"從雙足飛龍管理員迪弗拉克那裡租一隻馭風者飛往雷霆崖，然後將這捆獸皮交給雷霆崖的安哈努。"}},
[6363] = {"雙足飛龍管理員塔爾", {"將安哈努的皮貨交給雷霆崖的塔爾。"}},
[6364] = {"向加翰回覆", {"從雙足飛龍管理員塔爾那裡租用一頭飛往十字路口的雙足飛龍，並把安哈努的皮貨交給加翰·鷹翼。"}},
[6365] = {"送往奧格瑪的肉", {"把札爾夫的肉品交給十字路口的迪弗拉克。"}},
[6381] = {"新的生命", {"將10枚蓋亞之種種植在蓋亞土堆中，然後與烈日石居的塔姆拉談話。"}},
[6382] = {"梣谷狩獵", {"與梣谷碎木崗哨的塞娜尼·雷心談話。"}},
[6383] = {"梣谷狩獵", nil},
[6384] = {"飛往奧格瑪", {"從雙足飛龍管理員迪弗拉克那裡租一隻雙足飛龍飛往奧格瑪，然後將札爾夫的肉品交給奧格瑪的格雷什卡。"}},
[6385] = {"雙足飛龍管理員朵拉斯", {"將格雷什卡的信交給奧格瑪的朵拉斯。"}},
[6386] = {"返回十字路口", {"從雙足飛龍管理員朵拉斯那裡雇一隻馭風者前往十字路口，然後將格雷什卡的信交給十字路口的札爾夫。"}},
[6387] = {"榮譽學員", {"將布洛克的名單交給塞爾薩瑪的索格拉姆·伯雷森。"}},
[6388] = {"格萊斯·瑟登", {"將榮譽鋤交給鐵爐堡的格萊斯·瑟登。"}},
[6390] = {"瘟疫與你", {"使用北山伐木場裡的鐵棍放出那裡的瘟疫白蟻，然後向提里斯法林地亡靈壁壘的米克·萊文報告。"}},
[6391] = {"飛往鐵爐堡", {"從獅鷲獸管理員索格拉姆·伯雷森那裡租一隻獅鷲獸飛往鐵爐堡，然後將布洛克的名單交給鐵爐堡的高尼爾·石趾。"}},
[6392] = {"向布洛克回復", {"從獅鷲獸管理員格萊斯·瑟登那裡租用一頭飛往塞爾薩瑪的獅鷲獸，然後將榮譽鋤交給塞爾薩瑪的布洛克·尋石者。"}},
[6393] = {"元素戰爭", {"將10塊焚火餘燼交給烈日石居的蘇納曼。"}},
[6394] = {"塔茲利爾的鎬", {"將塔茲利爾的鎬還給塔茲利爾。"}},
[6395] = {"瑪拉的遺願", {"將山繆·菲普斯的遺骸帶到瑪拉的墳墓去，然後回到新兵艾爾雷斯那裡。"}},
[6401] = {"卡雅還活著", {"告訴烈日石居的塔姆拉·荒原這個好消息。"}},
[6421] = {"滾岩峽谷", {"深入滾岩峽谷的洞穴中，為烈日石居的摩羅加爾取回10塊共鳴水晶以供研究。"}},
[6441] = {"薩特之角", {"為碎木崗哨的皮克希爾收集16隻薩特的角。"}},
[6442] = {"佐拉姆海岸的納迦", {"將20顆怒尾納迦的頭顱交給佐拉姆海岸的瑪魯凱。"}},
[6461] = {"盜竊的蜘蛛", {"瑪拉卡金的辛吉拉要求你殺死10隻深苔爬行者和7隻深苔毒蜘蛛。"}},
[6462] = {"食人妖符咒", {"將8個食人妖符咒交給左拉姆加前哨站的米蘇瓦。"}},
[6481] = {"土靈的覺醒", {"使用魔化共鳴水晶打開共鳴桶，然後殺死高戈羅克。將這個消息告訴摩羅加爾，並把魔化共鳴水晶還給他。"}},
[6482] = {"盧爾的自由", {"護送盧爾，然後與碎木崗哨的雅瑪·雪蹄談話。"}},
[6501] = {"巨龍之眼", {"你必須尋遍世界以找到一種能恢復龍眼碎片的能量的生物。你對這種生物的唯一瞭解就是：他們確實存在。"}},
[6502] = {"龍火護符", {"你必須從達基薩斯將軍身上取回黑龍勇士之血。","","你可以在黑石塔的晉升大廳後面的房間裡找到達基薩斯。"}},
[6503] = {"梣谷先驅者", {"殺掉9個梣谷先驅者，然後回到碎木崗哨的庫萊比那裡。"}},
[6504] = {"丟失的書頁", {"找到丟失的12頁伐木機操作指南，把它們合併為第1、2、3章。然後帶著這些書頁回到碎木崗哨去找古爾達·怒痕。"}},
[6521] = {"邪惡的盟友", {"把瑪克林大使的頭顱交給幽暗城的瓦里瑪薩斯。"}},
[6522] = {"邪惡的盟友", {"把小卷軸交給幽暗城的瓦里瑪薩斯。"}},
[6523] = {"保護卡雅", {"護送卡雅·扁蹄回到阿帕拉耶營地，然後到石爪山東南邊界附近的瑪卡巴·扁蹄那裡去覆命。"}},
[6541] = {"向卡德拉克報到", {"到貧瘠之地北部的卡德拉克那裡報到。"}},
[6542] = {"向卡德拉克報到", {"到貧瘠之地北部的卡德拉克那裡報到。"}},
[6543] = {"戰歌報告", {"打開報告集，把戰歌報告交給戰歌斥候、戰歌信差和戰歌偵查騎兵。把他們的最新報告交給貧瘠之地北部哨塔上的卡德拉克。"}},
[6544] = {"托雷克的突襲", {"保護在銀翼哨站與杜瑞爾·月火作戰的托雷克，然後向慰籍之林的埃爾托格·怒齒彙報勝利的消息。"}},
[6545] = {"戰歌信差的報告", nil},
[6546] = {"戰歌偵查騎兵的報告", nil},
[6547] = {"戰歌斥候的報告", nil},
[6548] = {"為我的村莊復仇", {"殺掉8個恐怖圖騰惡徒和6個恐怖圖騰傭兵，然後向石爪山脈東南邊界處的瑪卡巴·扁蹄覆命。"}},
[6561] = {"黑澗深淵中的惡魔", {"把夢遊者克爾里斯的頭顱交給雷霆崖的巴珊娜·符文圖騰。"}},
[6562] = {"幫助耶努薩克雷", {"與梣谷的耶努薩克雷談話。"}},
[6563] = {"阿庫麥爾水晶", {"收集20顆阿庫麥爾藍寶石，把它們交給梣谷的耶努薩克雷。"}},
[6564] = {"上古之神的僕從", {"把潮濕的便箋交給梣谷的耶努薩克雷。"}},
[6565] = {"上古之神的僕從", {"殺掉黑澗深淵裡的洛古斯·傑特，然後回來找梣谷的耶努薩克雷。"}},
[6567] = {"部落的勇士", {"按照酋長的指示找到雷克薩。他在石爪山和菲拉斯之間的淒涼之地遊蕩。"}},
[6569] = {"黑龍幻象", {"到黑石塔去收集20顆黑色龍人的眼球，完成任務之後回到巫女米蘭達那裡。"}},
[6570] = {"艾博斯塔夫", {"去塵泥沼澤中的巨龍沼澤，找到艾博斯塔夫的洞穴。進入洞穴後帶上龍形護符，跟艾博斯塔夫交談。"}},
[6571] = {"戰歌氏族的補給品", {"收集戰歌族的補給品：戰歌鋸條、伐木繩、戰歌之油，還有一箱戰歌之斧。"}},
[6581] = {"戰歌鋸條", nil},
[6582] = {"龍骨試煉，斯克利爾", {"找到藍龍斯克利爾並殺掉他。從他的身上取下他的顱骨，然後將其交給艾博斯塔夫。","","你可以在冬泉谷找到斯克利爾。"}},
[6583] = {"龍骨試煉，索姆努斯", {"殺掉綠龍索姆努斯，把他的顱骨交給艾博斯塔夫。"}},
[6584] = {"龍骨試煉，克魯里裡斯", {"諾茲多姆的孩子克魯納里斯在塔納利斯沙漠守衛著時光之穴。殺了牠，把牠的顱骨交給艾博斯塔夫。"}},
[6585] = {"龍骨試煉，埃克托茲", {"到格瑞姆巴托去殺掉紅龍埃克托茲，把他的顱骨交給艾博斯塔夫。"}},
[6601] = {"晉升……", {"看來這場猜謎遊戲就要結束了。你知道米蘭達為你製作的龍形護符在黑石塔裡面無法發揮作用，也許你應該去找雷克薩，將你的困境告訴他。把黯淡的龍火護符給他看看，也許他知道下一步該怎麼做。"}},
[6602] = {"黑龍勇士之血", {"到黑石塔去殺掉達基薩斯將軍，把它的血交給雷克薩。"}},
[6603] = {"冬泉谷的麻煩！", {"到冬泉谷的溫泉附近尋找多諾瓦·雪山。"}},
[6604] = {"被激怒的梟獸", {"與墜星村的加隆·石矛談話。"}},
[6605] = {"奇怪的傢伙", nil},
[6607] = {"釣魚專家納特·帕格", {"納特·帕格要你釣到以下幾種魚：","","悲傷沼澤的蘆葦海岸大馬哈魚。","","淒涼之地的薩瑟里斯海岸虎魚。","","菲拉斯沃丹提斯河的菲拉斯草魚。","","荊棘谷的野人海岸藍色叉牙魚。","","當你釣到這些魚之後，就可以回去找納特·帕格了！"}},
[6610] = {"蚌肉大餐", {"迪爾格·奎克里弗想要你收集這些原料：","","12顆巨蛋。你可以在塔納利斯的大鵬或是其他大型鳥類那裡獲得這種蛋。","","10塊美味的蚌肉。你可以從任何蚌類身上獲得這種原料！","","20塊奧特蘭克冷酪。去買就是了！","","收集好所有原料，然後把它們交給迪爾格。"}},
[6611] = {"加基森之旅！", {"到塔納利斯沙漠的加基森去，與迪爾格·奎克里弗談談你的廚師生涯。"}},
[6612] = {"我認識一個傢伙…", {"到塔納利斯沙漠的加基森去，與迪爾格·奎克里弗談談你的廚師生涯。"}},
[6621] = {"汙林熊怪之王", {"把卡拉恩的旗子插到汙林圖騰堆中。不要讓熊怪摧毀這面旗子。擊敗穆戈特酋長，將穆戈特的圖騰交給左拉姆加的卡拉恩·阿瑪卡。"}},
[6622] = {"救死扶傷", {"使用急救繃帶來治療病人。你必須在6個病人死亡之前拯救15個病人。","","一定要牢記治療的順序！受致命傷的病人會很快死亡，其次是重傷病人，受普通傷的病人死亡得最慢。所以你最好在治療那些受致命傷和重傷的病人之後再去治療受普通傷的病人。"}},
[6623] = {"部落醫療隊", {"到阿拉希高地的落錘鎮去，與格里高利·維克托醫生談一談關於加入部落外科醫療隊的事宜。"}},
[6624] = {"救死扶傷", {"使用急救繃帶來治療病人。你必須在6個病人死亡之前拯救15個病人。","","一定要牢記治療的順序！受致命傷的病人會很快死亡，其次是重傷病人，受普通傷的病人死亡得最慢。所以你最好在治療那些受致命傷和重傷的病人之後再去治療受普通傷的病人。"}},
[6625] = {"聯盟醫療隊", {"到塵泥沼澤的塞拉摩去，與古斯塔夫·范沃森醫生談一談關於加入聯盟外科醫療隊的事宜。"}},
[6626] = {"邪惡之地", {"殺掉8個剃刀沼澤護衛者、8個剃刀沼澤織棘者和8個亡首教徒，然後向剃刀高地入口處的麥雷姆·月歌覆命。"}},
[6627] = {"知識試煉", {"成功回答布勞格·幽魂的問題，然後和他再次對話。他會一直在石爪山等你回答問題。"}},
[6628] = {"知識試煉", {"成功回答帕科瓦·芬塔拉斯的問題，然後再次和他對話。他會一直在幽暗城等你回答問題。"}},
[6629] = {"殺死格魯迪格·暗雲", {"殺掉格魯迪格·暗雲和6個恐怖圖騰蠻兵，然後向石爪山東南面的瑪卡巴·扁蹄覆命。"}},
[6641] = {"鞭笞者沃爾沙", {"在穆格拉什尋找火盆的過程中保障他的安全，幫助他熄滅火盆，然後在與納迦作戰時保護他。","","如果你成功了，就回到左拉姆加前哨站去，把鞭笞者沃爾沙的死訊通知給戰歌傳信者。"}},
[6661] = {"捕捉礦道老鼠", {"使用捕鼠者之笛捕獲5隻礦道老鼠，把它們引到蒙提那兒去。別忘了退還笛子。"}},
[6662] = {"我的兄弟，尼普希", {"把裝著神秘肉品的紙箱交給在暴風城礦道地鐵倉庫的尼普希。"}},
[6681] = {"拉文霍德莊園", {"把拉文霍德徽記交給拉文霍德莊園的法拉德，莊園就坐落在希爾斯布萊德的群山之中。","","你的智慧將在這次旅途中得到考驗。做好準備吧。"}},
[6701] = {"辛迪加徽章", nil},
[6761] = {"新的邊疆", {"與達納蘇斯的塞納里奧區的瑪斯雷·馭熊者談話。"}},
[6762] = {"拉比恩·薩圖納", {"與月光林地永夜港的拉比恩·薩圖納談話。月光林地在費伍德森林和冬泉谷之間，可以從木喉要塞中的一條通道抵達那裡。"}},
[6844] = {"檔案管理員阿姆伯爾", {"將異種蠍粘液包裹的物體交給月光林地永夜港的阿姆伯爾，他是塞納里奧議會的檔案管理員。"}},
[6921] = {"廢墟之間", {"把深淵之核交給梣谷左拉姆加前哨站裡的耶努薩克雷。"}},
[6922] = {"阿奎尼斯男爵", {"把奇怪的水球交給梣谷左拉姆加前哨站的耶努薩克雷。"}},
[6981] = {"發光的碎片", {"前往棘齒城尋找一個人，他能告訴你更多關於發光碎片的事。","","然後，將碎片送往被指示的地方。"}},
[7003] = {"被縮小的巨人", {"使用索爾賓的超級壓縮器來縮小菲拉斯的任意種類的巨人，將他們縮小到更容易控制的體積。從縮小過的巨人身上收集15份微縮殘渣，把它們交給菲拉斯被遺忘的海岸碼頭的索爾賓‧范達瑟。"}},
[7028] = {"扭曲的邪惡", {"為淒涼之地的維洛收集25個瑟萊德絲水晶雕像。"}},
[7029] = {"維利塔恩的污染", {"在瑪拉頓裡用天藍水瓶在橙色水晶池中裝滿水。","","在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。","","治療8株植物並殺死那些諾克賽恩幼體，然後向葬影村的瓦克·戰痕覆命。"}},
[7041] = {"維利塔恩的污染", {"在瑪拉頓裡用天藍水瓶在橙色水晶池中裝滿水。","","在維利斯塔姆藤蔓上使用裝滿水的天藍水瓶，使墮落的諾克賽恩幼體出現。","","治療8株植物並殺死那些諾克賽恩幼體，然後向尼耶爾前哨站的塔琳德莉亞覆命。"}},
[7044] = {"瑪拉頓的傳說", {"找回塞雷布拉斯節杖的兩個部分：塞雷布拉斯魔棒和塞雷布拉斯鑽石。","","然後設法和塞雷布拉斯對話。"}},
[7046] = {"塞雷布拉斯節杖", {"幫助贖罪的塞雷布拉斯製作塞雷布拉斯節杖。","","當儀式完成之後再和他談談。"}},
[7064] = {"大地的污染", {"殺死瑟萊德絲公主，然後回到淒涼之地葬影村附近的瑟琳德拉那裡覆命。"}},
[7065] = {"大地的污染", {"殺死瑟萊德絲公主，然後回到淒涼之地尼耶爾前哨站的守護者瑪蘭迪斯那裡覆命。"}},
[7066] = {"生命之種", {"到月光林地去找到雷姆洛斯，將生命之種交給他。"}},
[7067] = {"賤民的指引", {"閱讀賤民的指引，然後從瑪拉頓得到聯合墜飾，將其交給淒涼之地南部的半人馬賤民。"}},
[7068] = {"暗影殘片", {"從瑪拉頓收集10塊暗影殘片，然後把它們交給奧格瑪的尤塞爾奈。"}},
[7070] = {"暗影殘片", {"從瑪拉頓收集10塊暗影殘片，然後把它們交給塵泥沼澤塞拉摩島上的大法師特沃許。"}},
[7141] = {"霜狼地圖", {"進入奧特蘭克山谷並擊敗部落將軍德雷克塔爾。然後，再回去找奧特蘭克山脈的勘查員塔雷·石鎬。"}},
[7161] = {"試煉場", {"到主基地東南邊的蠻爪洞穴中去找到霜狼軍旗，然後把它交給拉格隆德。"}},
[7162] = {"試煉場", {"到奧特蘭克山谷的丹巴達爾西南邊找到冰翼洞穴，並取得雷矛軍旗。然後把軍旗交給奧特蘭克山脈的哈格丁中尉。"}},
[7201] = {"最後的元素", {"到黑石深淵去取得10份元素精華。你應該在那些作戰傀儡和傀儡製造者身上找找，另外，薇薇安‧拉格雷也提到了一些有關元素生物的話題。"}},
[7241] = {"保衛霜狼氏族", {"到希爾斯布萊德丘陵地區的奧特蘭克山谷去。找到拉格隆德並和他談談，然後成為霜狼氏族的士兵。"}},
[7261] = {"國王的命令", {"到希爾斯布萊德丘陵地區的奧特蘭克山谷去。到那裡之後，和哈格丁中尉談談。","","為了銅鬚的榮耀！"}},
[7321] = {"海龜湯", {"給塔倫米爾的克里斯多夫·傑弗寇特帶去10塊海龜肉和一些舒心草。"}},
[7341] = {"公平交易", nil},
[7342] = {"弓箭是給娘娘腔用的", nil},
[7383] = {"大地之冠", {"用月井的水裝滿紫水晶瓶，然後把它交給多蘭納爾的科瑞薩斯·月怒。"}},
[7441] = {"普希林和埃斯托爾迪", {"到厄運之槌去找到小鬼普希林。你可以使用任何手段從小鬼那裡得到埃斯托爾迪的咒術之書。","","找到咒術之書後，回到拉瑞斯小亭的埃斯托爾迪那裡。"}},
[7481] = {"精靈的傳說", {"到厄運之槌去尋找泰謬斯·尋夢者。向莫沙徹營地的先知科魯拉克報告你所找到的資訊。"}},
[7482] = {"精靈的傳說", {"到厄運之槌去尋找泰謬斯·尋夢者。向莫沙徹營地的先知科魯拉克報告你所找到的資訊。"}},
[7488] = {"蕾瑟塔蒂絲的網", {"把蕾瑟塔蒂絲的網交給菲拉斯羽月要塞的拉托尼庫斯·月矛。"}},
[7489] = {"蕾瑟塔蒂絲的網", {"把蕾瑟塔蒂絲的網交給非拉斯莫沙徹營地的塔羅·刺蹄。"}},
[7492] = {"莫沙徹營地", {"和菲拉斯莫沙徹營地的塔羅·刺蹄談話。"}},
[7494] = {"羽月要塞", {"和菲拉斯羽月要塞的拉托尼庫斯·月矛談話。"}},
[7498] = {"迦羅娜：潛行與詭計研究", {"將這本典籍交給它的主人。"}},
[7541] = {"為部落效力", nil},
[7562] = {"莫蘇爾·召血者", {"與燃燒平原的莫蘇爾·召血者談話。"}},
[7563] = {"血之狂暴", {"把30瓶狂暴野獸的血交給燃燒平原的莫蘇爾·召血者。"}},
[7601] = {"尼比的助手", {"與費伍德森林的伊普斯談話。"}},
[7602] = {"無暇的惡魔精華", {"費伍德的伊普斯要求你從三個不同的地區收集三塊無暇的惡魔精華，然後把它們交給他。","","艾薩拉的雷加斯薩特、費伍德森林的加德納爾軍團士兵和詛咒之地的地獄衛士斥候分別擁有一種無暇的惡魔精華。"}},
[7603] = {"克羅蘇斯的惡魔之核", {"在費伍德森林的碎痕谷中搜尋克羅蘇斯的屍體。當你找到屍體後，在他身上使用魔火，並等待克羅蘇斯復生。當這個地獄火被喚醒之後，幹掉他，從他的身上拿取克羅蘇斯的惡魔之核。","","把克羅蘇斯的惡魔之核交給費伍德森林的尼比。"}},
[7623] = {"魔王貝恩霍勒", {"從燃燒平原的戈瑟奇那裡購買暗影藥水。","","使用這種藥劑進入加德納爾，然後與魔王貝恩霍勒談話。"}},
[7626] = {"達斯莫拉之鈴", {"把10瓶暗影之力藥劑交給燃燒平原的戈瑟奇·邪眼。"}},
[7627] = {"黑暗戰車之輪", {"把6份大塊魔光碎片和25塊黑鐵礦石交給燃燒平原的戈瑟奇·邪眼。"}},
[7628] = {"末日蠟燭", {"把35塊黑龍鱗片交給燃燒平原的戈瑟奇·邪眼。"}},
[7629] = {"瓶中的小鬼", {"把瓶中的小鬼帶到通靈學院的鍊金實驗室中。在小鬼製造出羊皮紙之後，把瓶子還給戈瑟奇·邪眼。"}},
[7630] = {"奧金錠", {"把3塊奧金錠交給燃燒平原的戈瑟奇·邪眼。"}},
[7631] = {"克索諾斯恐懼戰馬", {"閱讀莫蘇爾的指南，並召喚出一匹克索諾斯恐懼戰馬，擊敗它，然後控制它的靈魂。"}},
[7652] = {"君王鎧甲的設計圖", nil},
[7656] = {"帝國鎧甲護胸", nil},
[7657] = {"君王鎧甲頭盔", nil},
[7701] = {"懸賞：工頭瑪托留斯", {"那個叫做工頭瑪托留斯的黑鐵矮人叛徒就藏在大熔爐的熔渣之池深處。","","殺死工頭瑪托留斯，將他的頭顱交給灼熱峽谷的偵查隊長洛洛爾以換取你的獎勵。"}},
[7703] = {"戈多克巨魔的事務", {"找到戈多克力量護手，並將它交給厄運之槌的克羅卡斯。","","根據克羅卡斯所說的，「傳說」自稱是王子的精靈托塞德林從一名戈多克巨魔手中偷走了那件神器。"}},
[7721] = {"壓縮器的動力", {"從菲拉斯被遺忘的海岸那裡的海元素和巨型海元素身上獲取10塊水元素核心，把它們交給碼頭附近的索爾賓·范達瑟。"}},
[7722] = {"絕密配方！", {"在大熔爐的熔渣之池中的某個地方，你可以找到工頭瑪托留斯偷走的秘密設計圖：熾熱助熔劑。找到這些設計圖，把它們還給灼熱峽谷的大鐵匠博恩奈特。"}},
[7723] = {"該死的胖手指！", {"漢瑟爾·重拳讓你殺掉20個重型作戰傀儡。","","重型作戰傀儡就在灼熱峽谷的大熔爐附近。當你殺死足夠多的傀儡後，就回去找漢瑟爾·重拳。"}},
[7724] = {"熔岩蜘蛛的威脅！", {"漢瑟爾‧重拳要你殺死灼熱峽谷中的20隻灼熱熔岩蜘蛛。你可以在灼熱峽谷的高地和熔岩池裡找到灼熱熔岩蜘蛛。","","當你殺死足夠的灼熱熔岩蜘蛛之後，回到漢瑟爾‧重拳那裡覆命。"}},
[7725] = {"更多被縮小的巨人！", {"使用索爾賓的超級壓縮器來縮小菲拉斯裡任意種類的巨人，將他們縮小到更容易控制的體積。從縮小過的巨人身上收集10份微縮殘渣，把它們交給菲拉斯被遺忘的海岸碼頭的索爾賓·范達瑟。"}},
[7726] = {"補充動力", {"從菲拉斯被遺忘的海岸那裡的海元素和巨型海元素身上獲取6塊水元素核心，把它們交給碼頭附近的索爾賓·范達瑟。"}},
[7727] = {"燻火龍", {"漢瑟爾·重拳要你去殺掉20隻燻火龍。","","燻火龍侵佔了熔渣之池中的那些岩漿池。熔渣之池就在灼熱峽谷的大熔爐中。","","當你殺死足夠數量的燻火龍後，就回到灼熱峽谷找漢瑟爾·重拳。"}},
[7728] = {"被盜：鼓風機和望遠鏡", {"找到冶煉鼓風機和偵查員的望遠鏡，把它們還給灼熱峽谷的監工斯克蘭格。","","你所知道的關於這些物品的惟一資訊是：它們肯定是被黑鐵矮人偷走的。冶煉鼓風機是鐵匠用的鍛造工具，偵查員的望遠鏡是偵查員所需的偵查工具。"}},
[7729] = {"工作機會：肅清競爭對手", {"殺死15個黑鐵工頭和15個黑鐵奴隸販子。完成任務之後就回去找監工斯克蘭格。"}},
[7730] = {"祖卡什的入侵", {"把20塊祖卡什蟲殼交給菲拉斯莫沙徹營地的哈杜肯·迅蹄。"}},
[7731] = {"毒刺鞭笞者", {"擊敗痛苦深淵中的毒刺鞭笞者，把它的腺體交給菲拉斯莫沙徹營地的哈杜肯·迅蹄。"}},
[7732] = {"祖卡什報告", {"把莫沙徹營地祖卡什報告交給奧格瑪暗巷區的基爾茲賓·鼓眼。"}},
[7733] = {"更高的品質", {"把10塊怒痕雪人的毛皮交給菲拉斯羽月要塞的普拉特·馬克格魯比。"}},
[7734] = {"更高的品質", {"把10塊怒痕雪人的毛皮交給菲拉斯莫沙徹營地的杉多爾·迅蹄。"}},
[7738] = {"完美的雪人毛皮", {"把完美的雪人毛皮交給菲拉斯莫沙徹營地的杉多爾·迅蹄。"}},
