[7815] = {"鉗嘴龜！", {"辛特蘭惡齒村的釣魚者卡圖姆要你去殺掉15隻海水鉗嘴龜。完成任務之後回到他那裡去覆命。"}},
[7816] = {"加莫里塔！", {"辛特蘭惡齒村的釣魚者卡圖姆要你去殺掉加莫里塔，並從它的屍體上找到卡圖姆的超級魚餌。","","卡圖姆說加莫里塔和其他海龜都在海岸附近活動。"}},
