[8120] = {"阿拉希盆地之戰！", {"進攻阿拉希盆地的礦坑、伐木場、鐵匠鋪和獸欄，然後向落錘鎮的屠殺者杜維爾覆命。"}},
[8151] = {"獵人護符", {"跟艾薩拉的奧汀克談話。"}},
[8152] = {"急速逃脫", {"前往聖光之願禮拜堂，向某人詢問你找到的浸水線索。"}},
[8153] = {"苔蹄快步者鹿角", {"將一副完好的苔蹄快步者鹿角交給艾薩拉的奧汀克。奧汀客居住在埃達拉斯廢墟東北部的懸崖頂。"}},
