[8231] = {"獵殺碎浪多頭怪", {"帶回6個碎浪多頭怪的鱗片給艾薩拉的奧汀克。奧汀克居住在埃達拉斯廢墟東北部的懸崖頂部。"}},
[8232] = {"神廟中的綠龍", {"將摩弗拉斯的牙齒交給艾薩拉的奧汀克。他住在埃達拉斯廢墟東北部懸崖的頂端。"}},
[8233] = {"簡單的要求", {"和拉文霍德莊園的喬拉齊·拉文霍德公爵談一談。"}},
[8234] = {"密封的藍袋子", {"從艾薩拉的木喉薩滿那兒取回密封的藍袋子，將它交給艾薩拉的大法師克希雷姆。"}},
[8235] = {"加密的碎片", {"將10片加密的碎片交給艾薩拉的大法師克希雷姆。"}},
[8236] = {"碧藍鑰匙", {"將碧藍鑰匙交給喬拉齊·拉文霍德公爵。"}},
[8249] = {"垃圾箱", nil},
[8250] = {"法師公會", {"尋找薩納斯並獲得見到大法師克希雷姆的通路。"}},
[8254] = {"幫助塞納里奧", {"尋找艾薩拉的奧汀克。"}},
[8255] = {"打獵者", {"收集4份健康的野鹿腺體並把它們帶給艾薩拉的奧汀克。奧汀克住在埃達拉斯廢墟東北部懸崖的頂部。"}},
[8256] = {"亡靈腐液", {"為艾薩拉的奧汀克帶回1份亡靈腐液。奧汀克住在埃達拉斯廢墟東北部懸崖的頂端。"}},
[8257] = {"摩弗拉斯之血", {"前往沉沒的神廟阿塔哈卡，殺死摩弗拉斯，將他的血液交給費伍德森林中的格雷塔·苔蹄。沉沒的神廟的入口就在悲傷沼澤。"}},
[8273] = {"奧蘭的感謝", nil},
[8275] = {"奪回希利蘇斯", {"和在希利蘇斯塞納里奧城堡裡的喚風者普勞豪恩談話。"}},
[8276] = {"奪回希利蘇斯", {"和在希利蘇斯塞納里奧城堡裡的喚風者普勞豪恩談話。"}},
[8277] = {"沙漠中的劇毒", {"希利蘇斯的塞納里奧城堡的比提克斯·斯巴格要你去收集8只石鞭蠍刺和8只掠沙蜘蛛毒牙。完成任務後回到她那裡。"}},
[8278] = {"諾格的最後一線希望", {"希利蘇斯塞納里奧城堡的比提克斯·斯巴格要你去收集3只石鞭巨鉗蠍刺，3只石鞭掠奪者刺，和3只石行蜘蛛毒牙。"}},
[8279] = {"暮光詞典", {"將暮光詞典的3章帶給希利蘇斯的隱士奧泰爾。"}},
[8280] = {"保護補給線", {"希利蘇斯的塞納里奧城堡的喚風者普勞豪恩要你去殺15個掘泥打擊者。"}},
[8281] = {"確保安全", {"希利蘇斯的塞納里奧城堡的喚風者普勞豪恩要你去殺20個掘泥摧毀者。"}},
[8282] = {"諾格的背包", {"到希利蘇斯南邊山區找回諾格的背包，並回到塞納里奧城堡交還給他。"}},
[8283] = {"通緝：死亡彎鉤", {"將死亡彎鉤的刺針帶給守衛隊長維斯·庫魯茲。"}},
[8284] = {"暮光的秘密", {"希利蘇斯的塞納里奧城堡的地理學家拉克斯班要你去收集8個暮光石板碎片。"}},
[8285] = {"沙漠隱士", {"帶著修補的石板去找希利蘇斯的隱士奧泰爾。"}},
[8287] = {"擺脫困境", {"將解譯過的碑文羊皮紙交給指揮官瑪爾利斯。"}},
[8304] = {"親愛的娜塔莉雅", {"希利蘇斯，指揮官瑪爾利斯要你去詢問銅鬚營地的矮人居住者。你可以在塞納里奧城堡南邊找到銅鬚營地。","","當你收集到需要的資訊再回去找指揮官瑪爾利斯。"}},
[8306] = {"深入瘋狂之口", {"希利蘇斯，塞納里奧城堡的指揮官瑪爾利斯要你去找尋他摯愛的娜塔莉亞。你所收集到的資訊指出，南方的雷戈蟲巢就是你可以找到娜塔莉亞·瑪爾利斯夫人的地方。","","別忘記在進入蟲巢之前先去拜訪銅鬚營地的矮人。他們可能有一些額外的工作和建議要給你。","","還有<name>，記得指揮官的話:「做你該做的...」"}},
[8307] = {"沙漠食譜", {"在塞納里奧城堡西方的暮光之錘營地尋找關於烹煮沙蟲肉的資訊。"}},
[8308] = {"布拉恩·銅鬚遺失的信", {"將布拉恩·銅鬚的信帶到希利蘇斯南邊的銅鬚營地去。"}},
[8309] = {"追查雕文", {"希利蘇斯銅鬚營地的魯特加爾·雕石想要你前往亞什蟲巢、佐拉蟲巢和雷戈蟲巢，從蟲巢中的雕文水晶上取下拓文。","","使用地質學家的抄錄工具包獲取古老雕文的摹本。完成任務後回到魯特加爾·雕石那兒。"}},
[8310] = {"破解密碼", {"希利蘇斯銅鬚營地的法蘭克爾·石橋想要你取回一個亞什異種蟲腦、一個佐拉異種蟲腦和一個雷戈異種蟲腦。完成任務後回到法蘭克爾那兒。"}},
[8311] = {"史波普的萬鬼節糖果！", {"和暴風城、鐵爐堡、達納蘇斯的旅店老闆們及鐵爐堡的塔瓦斯德·基瑟爾交談。完成要求的惡作劇來交換他們提供的糖果。","","帶著達納蘇斯的杏仁糖、諾姆瑞根的橡皮軟糖、暴風城的奶油杏仁花生糖，和鐵爐堡的薄荷糖去找暴風城孤兒院的賈斯伯。"}},
[8313] = {"分享知識", {"將破碎的食譜交給塞納里奧城堡旅店中的卡蘭德拉斯。"}},
[8317] = {"廚房助手", {"塞納里奧城堡的卡蘭德拉斯需要製作10個沙漠肉丸子的麵團。"}},
[8318] = {"秘密通訊", nil},
[8320] = {"暮光地王", {"殺死10個暮光地王, 然後向塞納里奧城堡的胡姆·蠻鬃回報。"}},
[8321] = {"卑鄙的維拉爾", {"把維拉爾的徽記之戒帶給塞納里奧城堡的胡姆·蠻鬃。"}},
[8323] = {"真實信仰者", {"隱士奧泰爾希望你能帶給他10份加密的暮光文件。"}},
[8365] = {"海盜的帽子！", {"塔納利斯熱砂港的傲慢的店主要你去幫他收集20頂南海海盜帽。"}},
[8366] = {"南海復仇", {"塔納利斯熱砂港的安全主管吉羅姆·比格維茲要你去幹掉10個南海海盜、10個南海劫掠者、10個南海碼頭工人和10個南海流氓。"}},
[8367] = {"無上的榮耀", {"把3枚奧特蘭克山谷榮譽獎章、3枚阿拉希盆地榮譽獎章、3枚戰歌峽谷榮譽獎章和3枚暗矛島嶼榮譽獎章交給戰場外的部落戰爭使者。"}},
