[8419] = {"小鬼的要求", {"將1塊惡魔布交給費伍德森林的伊普斯。"}},
[8421] = {"奇怪的材料", {"將10塊腐爛的木頭和4個血毒精華交給費伍德森林的伊普斯。"}},
[8422] = {"巨魔的羽毛", {"到沉沒的神廟去，從食人妖們身上獲取6枝巫毒羽毛。"}},
[8423] = {"戰士的血脈", {"在詛咒之地殺死7隻地獄野豬，然後回到部落英雄的靈魂那裡。"}},
[8424] = {"魔誓者之戰", {"殺死詛咒之地的魔誓祭司，然後回到部落英雄的靈魂那兒。"}},
[8425] = {"巫毒羽毛", {"將你從沉沒的神廟的食人妖身上得到的巫毒羽毛交給部落英雄的靈魂。"}},
