[8460] = {"木喉熊怪的盟友", {"格拉茲要你去殺死6個死木戰士、6個死木探路者以及6個死木園丁以證明自己的立場。完成後回到翡翠聖地附近的費伍德森林南方找他。"}},
[8461] = {"北方的死木熊怪", {"納菲恩要你去殺死6個死木守衛、6個死木復仇者和6個死木薩滿。再回到木喉要塞入口附近的費伍德森林北方找他。"}},
[8462] = {"與納菲恩交談", {"沿著費伍德森林的大路往北走並和一隻叫納菲恩的熊怪交談。他就在木喉要塞的入口守衛著。"}},
[8464] = {"冬泉熊怪的活動", {"薩爾法要你去殺死8個冬泉薩滿，8個冬泉巢穴守衛和8個冬泉巨熊怪。薩爾法就在冬泉谷的木喉要塞入口外面。"}},
[8465] = {"與薩爾法交談", {"通過木喉要塞前往冬泉谷。和薩爾法交談，他就在木喉要塞入口外守衛著。"}},
