[8467] = {"給納菲恩的羽毛", nil},
[8469] = {"給薩爾法的珠串", nil},
[8470] = {"死木儀祭圖騰", {"帶著死木儀式圖騰進入木喉要塞，看看有沒有熊怪對這物品有用途的。除非你達到中立聲望值或比他們更好，否則木喉不會跟你說話。"}},
[8471] = {"冬泉儀祭圖騰", {"將冬泉儀式圖騰帶進木喉要塞，看看是否有任何熊怪會使用這個物品。如果你沒有在木喉要塞達到中立或更高的聲望值，他們將不會與你交談。"}},
[8551] = {"船長的箱子", {"將斯莫特的箱子交給藏寶海灣的海克拜瑞·斯莫特。"}},
[8552] = {"刺著字母的腰帶", {"將刺著字母的腰帶還給他的主人。"}},
[8553] = {"船長的彎刀", {"與斯普羅格談話。"}},
[8554] = {"挑戰奈古拉什", {"將10塊燒烤禿鷹翅膀和5瓶密林葡萄酒帶到斯莫特船長的救生艇上去。","","然後殺死奈古拉什，將斯莫特的彎刀交給荊棘谷的斯莫特船長。"}},
[8893] = {"超級測蛋器", nil},
[9051] = {"毒性測試", {"用魔暴龍皮倒鉤刺傷一隻魔暴龍。完成任務後再回到安戈洛環形山找托爾瓦·尋路者。"}},
[9052] = {"血瓣毒藥", {"收集8個血帽和8個格里什毒針，交給安戈洛環形山的托爾瓦·尋路者。"}},
[9053] = {"更好的材料", {"前往沉沒的神廟底部，從守衛那取回腐爛的藤蔓並交給托爾瓦·尋路者。"}},
[9063] = {"托爾瓦·尋路者", {"與安戈洛環形山的托爾瓦·尋路者談一談。"}},
[60860] = {"請收下獎勵！", nil},
[60870] = {"特別快遞", nil},
[65593] = {"戀人的心臟", {"把艾芙琳娜‧莉蕾和艾薩克‧佩爾森的心臟交給詛咒神殿的凱倫丁。"}},
[65597] = {"誓縛", {"使用這對戀人的心臟，把夢魔召喚出來然後加以制伏，再把戀人的心臟送去給幽暗城魔法區的凱倫丁·哈加爾。"}},
[65601] = {"痛心的愛", {"和奧格瑪的瑪加爾交談。"}},
[65602] = {"愛為何物?", {"取回木雕刻像，然後交給暴風城法師區的『黑暗縛靈師』加金。"}},
[65603] = {"誓縛", {"使用木雕刻像來召喚夢魔並加以制伏，然後將木雕刻像還給已宰的羔羊旅店的『黑暗縛靈師』加金。"}},
[65604] = {"誓縛", {"使用乾癟的圍巾來召喚夢魔，然後加以制伏，再把乾癟的圍巾交給奧格瑪的甘盧爾·血眼。"}},
[65610] = {"真希望你也在這裡", {"調查梣谷的墜星湖，然後向奧格瑪的甘盧爾·血眼回報。"}},
[76156] = {"與大地之母一同追獵", {"潛入風險投資公司在雷霆崖東南方的礦坑、從爆破補給品的推車中收集5個爆鹽採礦炸藥，並到雷霆崖將它們交給波爾頓‧暗影圖騰。"}},
[76160] = {"與大地之母一同追獵", {"在雷霆崖北側收集8個風怒果，用研缽和搗杵將它們磨碎之後，回到雷霆崖將結果告訴波爾頓‧暗影圖騰。"}},
[76240] = {"與大地之母一同追獵", {"購買或捕捉一隻新鮮的美味小魚，接著用到雷霆崖在波爾頓‧暗影圖騰面前用刀具組處理小魚。"}},
[78088] = {"奇怪的文物", {"前往梣谷的邁斯特拉崗哨，將奧薩拉克斯寶珠交給『淨化者』德爾葛蘭。"}},
[78089] = {"來自暴風城的建議", {"將奧薩拉克斯寶珠帶去給暴風城的純潔的凱薩琳。"}},
[78090] = {"多方意見", {"在暴風城內尋找術士聖所，並詢問關於珠子的事。"}},
[78091] = {"爭取你的鹽巴", {"在赤脊山的黑石召喚師身上收集 14 個召喚者之鹽，接著再回到暴風城找厄蘇拉·德林。"}},
[78092] = {"它必須被銷毀", {"從梣谷的惡魔身上收集12份瑪諾洛斯微粒。將它們和奧薩拉克斯寶珠一起帶去屠魔峽谷的瑪諾洛斯之矛處。"}},
[78093] = {"回去找德爾葛蘭", {"將寶珠裂片交給德爾葛蘭。"}},
