[94369] = {"微風島的命運", {"在瓦拉納爾和塔拉尼斯‧影歌交談。"}},
[94373] = {"土之召喚", {"把2個霜鬃熊紋墜飾交給安威瑪的提歐‧錘暴。"}},
[94374] = {"土之召喚", {"找到靈魂之石並喝下大地靈契。"}},
[94375] = {"土之召喚", {"將粗石英帶去給安威瑪的提歐‧錘暴。"}},
[94399] = {"暴掠龍的糧食", {"為安戈洛環形山的莫維克收集5份雙帆龍肉和5份翼手龍肉。"}},
[94411] = {"愛管閒事的法師", {"在申德高地殺死6名高天盟學徒。"}},
[94413] = {"對魔法的侮辱", {"在申德高地殺死6名塑風者見習先知。"}},
[94414] = {"微風島之錨", {"與哈剌‧鷹眼交談，並藉著他的能力，從遠方觀看錨塔。"}},
[94427] = {"神性的教誨", {"到幽暗城與塔尼斯‧奧德伍德交談。"}},
[94434] = {"神性的教誨", {"把10個亞麻布交給幽暗城的塔尼斯‧奧德伍德。"}},
[94435] = {"神性的教誨", {"回到班達利昂要塞找丹妮莎‧莫爾。"}},
[94436] = {"神性的教誨", {"在班達利昂要塞與亡靈衛兵比爾穆交談。","","如果你弄丟生命符記的話，就再回去找丹妮莎‧莫爾拿一個。"}},
[94438] = {"神性的教誨", {"帶著生命符記，然後在毒蛛峽谷讓亡靈衛兵法爾根復生。","","如果你弄丟生命符記的話，就再回去找丹妮莎‧莫爾拿一個。"}},
[94440] = {"神性的教誨", {"在毒蛛峽谷從血色十字軍身上取回血色十字軍攻擊計畫，然後回到班達利昂要塞找亡靈衛兵比爾穆。"}},
[94441] = {"神性的教誨", {"到班達利昂要塞內和丹妮莎‧莫爾交談。"}},
[94449] = {"火之召喚", {"到丹莫洛找布魯格斯‧燃裔。"}},
[94465] = {"火之召喚", {"把眠炎火炬交給洛克莫丹的布拉迪爾‧塵披。"}},
[94466] = {"火之召喚", {"找到1個火焰焦油和1個試劑袋，把它們交給洛克莫丹的布拉迪爾‧塵披。"}},
[94467] = {"火之召喚", {"擊敗小型火焰之靈體，將餘燼放在恒焰聖殿屋頂的火盆裡。"}},
[94468] = {"火之召喚", {"將恆焰火炬交給丹莫洛的布魯格斯‧燃裔。"}},
[94472] = {"大地靈契", nil},
[94479] = {"彼之垃圾", {"在污化丘陵四處查訪，尋找對你找到的金屬物體感興趣的人。"}},
[94480] = {"敵人的禮物", {"將遭竊的飼料交給羅格瑪的高格。"}},
[94481] = {"補充能量", {"讓訓練場的8個羅格瑪受訓者飽餐一頓。"}},
[94483] = {"給他們一點顏色瞧瞧", {"在南邊河畔殺死8個遠境堡牧師和12個遠境堡斥候。"}},
[94484] = {"令人不安的寂靜", {"到影風森林東北方找到伊蕾嘉兒‧荊爪，並與她交談。"}},
[94485] = {"女士之淚", {"收集8個女士之淚苔蘚。"}},
[94486] = {"包紮用羽毛", {"在影風森林從影風始祖鳥身上收集20根羽毛。"}},
[94487] = {"不屑為伍也不夠格之人", {"在影風森林從奧拉凱斯步行兵和奧拉凱斯追風者身上收集10個染血傳家寶。"}},
[94488] = {"解不開的結", {"殺死指揮官哈利安，然後把他的頭顱交給影風森林的伊蕾嘉兒‧荊爪。"}},
[94489] = {"背叛的傷痕", {"進入夜牙巢穴，治癒7名德魯伊，然後到影風森林找喬瑞爾‧風詠。"}},
